window.TXB=window.TXB||{};TXB["alab/2Sa"]={"1:1":"وبعد موت شاول وعودة داود من محاربة العمالقة مكث داود في صقلغ يومين.","1:2":"وأقبل رجل في اليوم الثالث من معسكر شاول بثياب ممزقة ورأس معفر وخر عند قدمي داود ساجدا.","1:3":"فسأله داود: «من أين أقبلت؟» فأجاب: «من معسكر إسرائيل ناجيا بنفسي».","1:4":"فسأله داود: «ماذا جرى؟ أخبرني» فقال: «لقد هرب الجيش من ساحة القتال، وقتل جمع غفير منهم، ومات شاول وابنه يوناثان أيضا»","1:5":"فسأله داود: «كيف عرفت بموت شاول وابنه يوناثان؟»","1:6":"فأجاب: «صادف أنني كنت في جبل جلبوع عندما رأيت شاول يتوكأ على رمحه وعربات الأعداء وفرسانهم يتعقبونه.","1:7":"ومالبث أن التفت وراءه. وحين شاهدني استدعاني إليه.","1:8":"وسألني: من أنت؟ فأجبت: عماليقي","1:9":"فقال لي: قف علي واقتلني لأنني أقاسي من فرط الألم، والحياة مازالت تسري في جسدي.","1:10":"فوقفت عليه وقتلته، لأنني أدركت أنه ميت لا محالة بعد سقوطه، فأخذت الإكليل الذي فوق رأسه والسوار الذي على ذراعه وأتيت بهما إلى سيدي».","1:11":"فمزق داود ورجاله الذين معه ثيابهم.","1:12":"وندبوا وناحوا وصاموا إلى المساء على شاول وعلى بني إسرائيل الذين قتلوا في المعركة.","1:13":"ثم قال داود للرجل الذي أبلغه النبأ: «من أين أنت؟» فقال: «أنا ابن رجل غريب، عماليقي»","1:14":"فقال داود: «كيف جرؤت أن تمد يدك لتقتل الملك مختار الرب؟»","1:15":"وأمر داود أحد رجاله قائلا: «تقدم، واقتله». فأغمد فيه سيفه فمات.","1:16":"وقال داود: «دمك على رأسك، لأن فمك شهد عليك بعد اعترافك أنك قتلت مختار الرب».","1:17":"ورثا داود شاول وابنه يوناثان بهذه المرثاة،","1:18":"وأمر أن يتعلمها بنو يهوذا، وهي بعنوان: «نشيد القوس» المدونة في سفر ياشر.","1:19":"«مجدك، مجدك يا إسرائيل صريع فوق روابيك. كيف تهاوى الأبطال؟","1:20":"لا تخبروا في جت، ولا تبشروا في شوارع أشقلون، لئلا تفرح بنات الفلسطينيين، لئلا تشمت بنات الغلف.","1:21":"يا جبال جلبوع، لا يكن عليكن طل ولا مطر، ولا حقول تغل محاصيل تقدمات، لأن هناك تهاوى ترس الأبطال. ترس شاول لم يعد يلمع بالزيت.","1:22":"من دم القتلى، ومن لحم الشجعان لم يرتد قوس يوناثان، وسيف شاول لم يرجع مخفقا.","1:23":"شاول ويوناثان المحبوبان، ومثارا الإعجاب في حياتهما لم يفترقا حتى في الموت. كانا أخف من النسور، وأقوى من الأسود.","1:24":"يا بنات إسرائيل، نحن على شاول الذي ألبسكن ثياب القرمز ورفهكن وزين ثيابكن بالحلي الذهبية.","1:25":"كيف تهاوى الأبطال في خضم الحرب؟ يوناثان على روابيك مقتول.","1:26":"لشد ما تضايقت عليك يا أخي يوناثان. كنت عزيزا جدا علي، ومحبتك لي كانت محبة عجيبة، أروع من محبة النساء.","1:27":"كيف تهاوى الأبطال وفنيت عدة القتال».","2:1":"ثم استشار داود الرب: «هل أتوجه إلى إحدى مدن يهوذا؟» فأجابه الرب: «اذهب». فسأل: «إلى أية مدينة؟» فأجابه: «إلى حبرون».","2:2":"فانطلق داود إلى هناك بصحبة زوجتيه أخينوعم اليزرعيلية وأبيجايل أرملة نابال الكرملي.","2:3":"واصطحب معه رجاله وأهل بيوتهم، فأقاموا في مدن حبرون.","2:4":"وجاء رجال يهوذا فنصبوا داود ملكا عليهم. وعندما علم داود أن رجال يابيش جلعاد هم الذين دفنوا شاول،","2:5":"بعث إليهم برسل قائلا: «لتكونوا مباركين من الرب لأنكم صنعتم هذا المعروف بسيدكم شاول فدفنتموه.","2:6":"فليكافئكم الرب إحسانا وخيرا، وأنا أيضا أجازيكم خيرا لقاء حسن عملكم.","2:7":"والآن تشجعوا وكونوا أبطالا لأن سيدكم مات، وقد نصبني بيت يهوذا ملكا عليكم».","2:8":"وأما أبنير بن نير قائد جيش شاول فأخذ إيشبوشث بن شاول واجتاز به الأردن إلى محنايم،","2:9":"وأقامه ملكا على الجلعاديين والأشيريين واليزرعيليين وعلى بني أفرايم وبني بنيامين وسائر إسرائيل.","2:10":"وكان إيشبوشث بن شاول في الأربعين من عمره حين ملك على إسرائيل، وظل في الحكم سنتين، أما سبط يهوذا فقد التف حول داود.","2:11":"وملك داود في حبرون على سبط يهوذا سبع سنوات وستة أشهر.","2:12":"وتوجه أبنير بن نير مع بعض قوات إيشبوشث من محنايم إلى جبعون،","2:13":"وكذلك خرج يوآب بن صروية مع بعض قوات داود فالتقوا جميعا عند بركة جبعون، فجلس كل فريق مقابل الآخر على جانبي البركة.","2:14":"فقال أبنير ليوآب: «ليقم جنودنا للمبارزة أمامنا». فأجاب يوآب: ليقوموا.","2:15":"فهب اثنا عشر رجلا من بني بنيامين من أتباع إيشبوشث واثنا عشر من قوات داود.","2:16":"واشتبك كل واحد مع نده وأغمد سيفه فيه، فماتوا جميعا. ودعي ذلك الموضع «حلقث هصوريم» (ومعناه حقل السيوف). التي هي في جبعون.","2:17":"واشتد القتال في ذلك اليوم، فانكسر أبنير ورجاله أمام قوات داود.","2:18":"وكان من جملة رجال داود هناك أبناء صروية: يوآب وأبيشاي وعسائيل. وكان عسائيل سريع العدو كالغزال البري.","2:19":"فتعقب عسائيل أبنير ولم يمل عنه يمنة أو يسرة.","2:20":"فالتفت أبنير وراءه وتساءل: «هل أنت عسائيل؟ فأجاب: «أنا هو».","2:21":"فقال له: «تنح عني واقبض على أحد الرجال الآخرين واسلبه سلاحه». غير أن عسائيل ظل يسعى في أثره.","2:22":"ثم عاد أبنير يلح على عسائيل أن يكف عنه قائلا: «لماذا تدفعني إلى قتلك؟ وكيف يمكنني أن أواجه أخاك يوآب إذا قتلتك؟»","2:23":"لكن عسائيل أبى أن يتنحى عنه، فطعنه أبنير بعقب الرمح، فغاص الرمح في بطنه وخرج من ظهره، فوقع صريعا ومات في مكانه. فكان كل من يمر بالموضع الذي صرع فيه عسائيل يتوقف عنده.","2:24":"وطارد يوآب وأبيشاي أبنير حتى مغيب الشمس حيث أتيا إلى تل أمة مقابل جيح الواقعة على طريق صحراء جبعون.","2:25":"فاجتمع أبناء بنيامين وراء أبنير في قوة واحدة واصطفوا على رأس تل واحد.","2:26":"فنادى أبنير يوآب قائلا: «أينبغي للسيف أن يظل ينهش إلى الأبد؟ ألم تعلم أن عاقبة القتال هي مرارة؟ فإلى متى لا تأمر جيشك بالارتداد عن إخوتهم؟»","2:27":"فقال يوآب: «حي هو الله فإنه لو لم تتكلم لتعقب رجالي في الصباح إخوتهم».","2:28":"ونفخ يوآب بالبوق فكف جميع جيشه عن مطاردة الإسرائيليين وامتنعوا عن المحاربة.","2:29":"فانطلق أبنير ورجاله طوال الليل عبر وادي الأردن وظلوا يجدون في السير إلى أن بلغوا محنايم.","2:30":"ورجع يوآب عن أبنير، وجمع جيشه، فوجد أن المفقودين من قوات داود تسعة عشر رجلا بالإضافة إلى عسائيل.","2:31":"أما الذين ماتوا من البنيامينيين ومن رجال أبنير على أيدي قوات داود فكانوا ثلاث مئة وستين رجلا.","2:32":"ونقلوا عسائيل ودفنوه في قبر أبيه في بيت لحم. وسار يوآب ورجاله الليل كله حتى وصلوا حبرون عند الفجر.","3:1":"وطالت الحرب بين بيت شاول وبيت داود، وكان داود يزداد قوة وبيت شاول يتفاقم ضعفا.","3:2":"وأنجب داود بنين في حبرون، كان أكبرهم أمنون من أخينوعم اليزرعيلية.","3:3":"والثاني كيلآب من أبيجايل أرملة نابال الكرملي، والثالث أبشالوم ابن معكة بنت تلماي ملك جشور،","3:4":"والرابع أدونيا بن حجيث، والخامس شفطيا بن أبيطال،","3:5":"والسادس يثرعام ابن عجلة امرأة داود.","3:6":"وفي غضون الحرب التي نشبت بين بيت شاول وبيت داود قوي نفوذ أبنير في أوساط بيت شاول.","3:7":"وكان لشاول محظية اسمها رصفة بنت أية، فقال إيشبوشث لأبنير: «لماذا ضاجعت محظية أبي؟»","3:8":"فاستشاط أبنير غيظا من كلام إيشبوشث، وقال له: «هل أنا رأس كلب ليهوذا! إلى هذا اليوم وأنا أبذل ولائي في سبيل بيت شاول وإخوته وأصحابه، ولم أسلمك ليد داود، والآن تتهمني بانتهاك عرض المرأة؟","3:9":"ليعاقب الرب أبنير أشد عقاب إن لم أناصر داود كما وعده الرب","3:10":"أن ينقل المملكة من بيت شاول ويوليه على عرش إسرائيل ويهوذا من دان إلى بئر سبع».","3:11":"فلم ينبس إيشبوشث بحرف خوفا من أبنير.","3:12":"وبعث أبنير على الفور رسلا إلى داود قائلا: من هو صاحب البلاد؟ أبرم معي ميثاقا فأناصرك بضم جميع أسباط إسرائيل إليك».","3:13":"فأجابه داود: «حسنا، أنا أبرم معك ميثاقا، إلا أنني أشترط عليك أمرا واحدا، هو أن تأتي أولا بميكال بنت شاول حين تأتي لمقابلتي، وإلا فلن ترى وجهي».","3:14":"وبعث داود رسلا إلى إيشبوشث بن شاول قائلا: «أعطني امرأتي ميكال التي خطبتها بمئة من غلف الفلسطينيين».","3:15":"فأرسل إيشبوشث وأخذها من عند رجلها فلطيئيل بن لايش.","3:16":"فراح رجلها يسير معها باكيا وراءها حتى مدينة بحوريم، إلى أن أمره أبنير: «امض. ارجع». فرجع.","3:17":"وقال أبنير لشيوخ إسرائيل: «منذ زمن وأنتم تطالبون أن يكون داود عليكم ملكا.","3:18":"فالآن افعلوا، لأن الرب وعد داود قائلا: بقيادة داود عبدي أنقذ شعبي إسرائيل من الفلسطينيين ومن سائر أعدائهم».","3:19":"ثم تداول أبنير الأمر مع شيوخ سبط بنيامين، وبعد ذلك توجه إلى حبرون ليبلغ داود ما تم الاتفاق عليه بينه وبين رؤساء إسرائيل.","3:20":"وجاء أبنير إلى داود في حبرون بصحبة عشرين رجلا، فأقام داود مأدبة لهم،","3:21":"ثم قال ابنير لداود: «دعني أذهب على الفور لأجمع لسيدي الملك جميع أسباط إسرائيل ليبايعوك ملكا عليهم فيتحقق ما تصبو إليه». فشيعه داود ومضى بسلام.","3:22":"وما لبث أن وصل يوآب مع بعض رجاله قادمين من غزوة أصابوا فيها غنيمة عظيمة. وكان أبنير آنئذ قد غادر حبرون بعد أن شيعه داود بسلام.","3:23":"فقيل ليوآب: «قد وفد أبنير بن نير على الملك، فأطلقه الملك مشيعا بالسلامة».","3:24":"فمثل يوآب في حضرة الملك وقال: «ماذا فعلت؟ لقد أقبل إليك أبنير، فلماذا تركته يمضي بسلام؟","3:25":"أنت تعلم أن أبنير بن نير لم يأت إلا ليتملقك ويتجسس عليك ويطلع على كل ما تصنع».","3:26":"ثم خرج يوآب من لدن داود وأرسل رسلا وراء أبنير فردوه من بئر السيرة من غير علم داود.","3:27":"وعندما رجع أبنير إلى حبرون انتحى به يوآب جانبا عند منتصف بوابة المدينة، وكأنه يريد أن يسر إليه بشيء، وطعنه في بطنه فمات انتقاما لدم عسائيل.","3:28":"وما إن علم داود بذلك حتى قال: «بريء أنا ومملكتي أمام الرب إلى الأبد من دم أبنير بن نير.","3:29":"ولينصب دمه على رأس يوآب وعلى كل بيت أبيه، ولا ينقطع من بيت يوآب مصاب بالسيلان وبالبرص وبالعرج، وصريع بالسيف ومفتقر إلى الخبز».","3:30":"وهكذا قتل يوآب وأبيشاي أخوه أبنير ثأرا لسفكه دم عسائيل أخيهما في جبعون في الحرب.","3:31":"وأمر داود يوآب وسائر الشعب الذي معه قائلا: «مزقوا ثيابكم وارتدوا المسوح، والطموا وجوهكم نوحا على أبنير». وكان داود الملك يمشي خلف النعش.","3:32":"وتم دفن أبنير في حبرون، وناح الملك بصوت مرتفع على قبر أبنير وبكاه جميع الشعب.","3:33":"ورثا الملك أبنير قائلا: «أهكذا يموت أبنير كموت أحمق؟","3:34":"يداك لم تكونا مغلولتين، ورجلاك لم تكونا مصفدتين بسلاسل النحاس. مت كمن يصرعه الأشرار». وعاد جميع الشعب يندبونه من جديد.","3:35":"وعندما جاء من يقدم لداود طعاما في أثناء النهار، أقسم داود قائلا: «ليعاقبني الرب أشد عقاب ويزد، إن كنت أذوق خبزا أو أي شيء آخر قبل غروب الشمس».","3:36":"فذاع الأمر بين الشعب وحظي داود برضاهم مثلما حظي برضاهم بمآثره السابقة.","3:37":"وأدرك كل شعب إسرائيل في ذلك اليوم أنه لم يكن للملك يد في مقتل أبنير بن نير.","3:38":"وقال الملك لحاشيته: «ألا تعلمون أن قائدا ورجلا عظيما قد سقط اليوم في إسرائيل؟","3:39":"وها أنا، على الرغم من أنني الملك الممسوح، فإنني أضعف من أبناء صروية؟ إنهم أقوى مني. ليجاز الرب مرتكب الشر بموجب شره».","4:1":"وعندما سمع إيشبوشث بمقتل أبنير في حبرون ارتعب واستولى الخوف على الإسرائيليين.","4:2":"وكان على رأس فرق الغزاة التابعة لابن شاول قائدان أخوان، هما بعنة وركاب ابنا رمون البئيروتي من بني بنيامين، لأن بئيروت حسبت في عداد ميراث سبط بنيامين،","4:3":"لأن أهل بئيروت فروا إلى جتايم وتغربوا هناك إلى هذا اليوم.","4:4":"وكان ليوناثان بن شاول ابن يدعى مفيبوشث قد أصيب برجليه وهو في الخامسة من عمره، عندما حملته مربيته وهربت به مسرعة بعد أن ذاع خبر مقتل شاول ويوناثان في يزرعيل فوقع من بين يديها وأصبح أعرج.","4:5":"وانطلق ركاب وبعنة ابنا رمون البئيروتي ودخلا عند اشتداد وطأة حر النهار إلى بيت إيشبوشث وهو نائم وقت القيلولة،","4:6":"فدخلا إلى وسط البيت، متظاهرين أنهما قد جاءا ليأخذا قمحا،","4:7":"وكان إيشبوشث آنئذ مضطجعا على سريره في مخدع نومه، فطعناه وقتلاه وقطعا رأسه وحملاه وجدا في الهرب طوال الليل عبر طريق العربة.","4:8":"وأتيا برأس إيشبوشث إلى داود في حبرون وقالا: «ها هو رأس إيشبوشث بن شاول، عدوك الذي كان يسعى إلى قتلك، وهوذا الرب قد انتقم اليوم لسيدي الملك من شاول ومن نسله».","4:9":"فقال داود لركاب وبعنة أخيه، ابني رمون البئيروتي: «حي هو الرب الذي فدى نفسي من كل ضيق،","4:10":"إن كنت قد قبضت على من خبرني أن شاول قد مات، وقتلته في صقلغ، وقد ظن في نفسه أنه يحمل لي بشارة سارة، فكان موته جزاء بشارته،","4:11":"فماذا أفعل بالأحرى برجلين باغيين يقتلان رجلا بريئا في بيته وعلى سريره؟ ألا أطالب الآن بدمه من أيديكما وأستأصلكما من الأرض؟»","4:12":"وأمر داود رجاله فقتلوهما وقطعوا أيديهما وأرجلهما، وعلقوا جثتيهما على البركة في حبرون. وأما رأس إيشبوشث فأخذوه وواروه في قبر أبنير في حبرون.","5:1":"وتوافد جميع رؤساء أسباط إسرائيل إلى داود في حبرون قائلين: «إننا لحمك وعظمك.","5:2":"وفي الأيام الغابرة عندما كان شاول ملكا علينا كنت أنت قائدنا في المعارك، وقد قال الرب لك: «أنت ترعى شعبي إسرائيل وتتولى حكمه».","5:3":"وفي حضور شيوخ إسرائيل في حبرون قطع الملك داود معهم عهدا أمام الرب، فنصبوه ملكا على إسرائيل.","5:4":"وكان داود في الثلاثين من عمره حين توج ملكا.","5:5":"واستمر ملكه أربعين سنة، منها سبع سنوات وستة أشهر ملك فيها على يهوذا في حبرون، وثلاث وثلاثون سنة ملك فيها في أورشليم على جميع أسباط إسرائيل وسبط يهوذا.","5:6":"ثم تقدم الملك بقواته نحو أورشليم لمحاربة أهلها اليبوسيين. فقالوا لداود: «لن تستطيع اقتحام المدينة، لأنه حتى في وسع العميان والعرج أن يصدوك عنها».","5:7":"غير أن داود استولى على حصن صهيون المعروف الآن بمدينة داود.","5:8":"وكان داود قد قال لرجاله: «على من يهاجم اليبوسيين أن يستخدم القناة للوصول إلى هؤلاء «العمي والعرج» الذين تبغضهم نفسي». لذلك يقال: «لا يدخل بيت الرب أعمى ولا أعرج».","5:9":"وأقام داود في الحصن ودعاه مدينة داود.","5:10":"وكان داود يزداد عظمة، لأن الرب القدير كان معه.","5:11":"وأرسل حيرام ملك صور وفدا إلى داود محملا بخشب أرز ونجارين وبنائين، فشيدوا لداود قصرا.","5:12":"وأدرك داود أن الرب قد ثبته ملكا على إسرائيل، وأنه قد عظم من ملكه من أجل شعبه إسرائيل.","5:13":"وبعد أن انتقل داود من حبرون إلى أورشليم اتخذ لنفسه زوجات ومحظيات وأنجب أبناء وبنات.","5:14":"وهذه هي أسماء أبناء داود الذين ولدوا في أورشليم: شموع وشوباب وناثان وسليمان.","5:15":"ويبحار وأليشوع ونافج ويافيع.","5:16":"وأليشمع وأليداع وأليفلط.","5:17":"وعندما علم الفلسطينيون أن داود اعتلى عرش إسرائيل خرجوا بقواتهم للبحث عنه. فلما بلغ الخبر داود لجأ إلى الحصن.","5:18":"وجاء الفلسطينيون وانتشروا في وادي الرفائيين.","5:19":"وسأل داود الرب: «هل أصعد لمحاربة الفلسطينيين؟ هل تنصرني عليهم؟» فأجابه الرب: «اصعد لأني أنصرك عليهم».","5:20":"فتقدم داود نحو بعل فراصيم وهاجمهم قائلا: «قد اقتحم الرب أعدائي أمامي كما تقتحم المياه». لذلك دعي ذلك الموضع بعل فراصيم.","5:21":"وهرب الفلسطينيون مخلفين وراءهم أصنامهم فحطمها داود ورجاله.","5:22":"ثم عاد الفلسطينيون فاحتلوا وادي الرفائيين وانتشروا فيه.","5:23":"فاستشار داود الرب، فقال له: «لا تصعد إليهم مواجهة، بل التف حولهم واهجم عليهم من ورائهم مقابل أشجار البلسم.","5:24":"وعندما تسمع صوت خطوات تنتقل فوق قمم أشجار البلسم فأسرع بالهجوم لأن الرب آنئذ يكون قد تقدمك للقضاء على معسكرهم».","5:25":"فنفذ داود أوامر الرب وقضى على الفلسطينيين من جبع إلى مدخل جازر.","6:1":"وحشد داود ثلاثين ألفا من صفوة المختارين من رجال إسرائيل،","6:2":"وانطلق بهم من بعلة يهوذا لينقلوا من هناك تابوت عهد الرب القدير الجالس فوق الكروبيم.","6:3":"فوضعوا تابوت الله على عربة جديدة وحملوه من بيت أبيناداب القائم على التلة، وكان كل من عزة وأخيو ابني أبيناداب يسوقان العربة الجديدة","6:4":"التي عليها تابوت الله. وكان أخيو يسير أمام التابوت،","6:5":"وداود وسائر مرافقيه من الإسرائيليين يعزفون أمام الرب على كل أنواع الآلات المصنوعة من خشب السرو، كالعيدان والرباب والدفوف والجنوك والصنوج.","6:6":"وعندما بلغوا بيدر ناخون تعثرت الثيران التي تجر العربة، فمد عزة يده وأمسك تابوت الرب خوفا عليه من السقوط.","6:7":"فاحتدم غضب الرب عليه، وأهلكه لأجل جسارته وجهله، فمات هناك بجوار التابوت.","6:8":"فشق الأمر على داود لأن الرب أهلك عزة وأباده. ودعا ذلك الموضع فارص عزة (ومعناه انكسار عزة) إلى هذا اليوم.","6:9":"وانتاب داود الخوف من الرب وقال: «كيف آخذ تابوت الرب عندي؟»","6:10":"ولم يرد أن ينقل تابوت الرب إليه في مدينة داود، فأودعه بيت عوبيد أدوم الجتي.","6:11":"ومكث التابوت في بيت عوبيد ثلاثة أشهر، وبارك الرب عوبيد وكل أهل بيته.","6:12":"وقيل لداود إن الرب بارك بيت عوبيد أدوم وجميع ماله بفضل تابوت الرب، فمضى داود وأحضر تابوت الرب من بيت عوبيد أدوم إلى مدينة داود ببهجة.","6:13":"وكان كلما خطا حاملو التابوت ست خطوات يذبح داود ثورا وعجلا معلوفا.","6:14":"وراح داود يرقص بكل قوته في حضرة الرب وهو متنطق بأفود من كتان.","6:15":"وهكذا نقل داود وكل إسرائيل تابوت الرب وسط الهتاف وأصوات الأبواق.","6:16":"ولما دخل موكب تابوت الرب مدينة داود، أطلت ميكال بنت شاول من الكوة، وشاهدت الملك داود يقفز ويرقص في حضرة الرب، فاحتقرته في نفسها.","6:17":"ثم أدخلوا تابوت الرب إلى الخيمة التي نصبها داود، وأقاموه في وسطها وقرب داود محرقات أمام الرب، وذبائح سلام.","6:18":"وحين فرغ داود من إصعاد المحرقات وذبائح السلام بارك الشعب باسم الرب القدير.","6:19":"ووزع على كل واحد من الإسرائيليين، رجالا ونساء، رغيف خبز وكأس خمر وقرص زبيب، ثم توجه كل واحد إلى بيته.","6:20":"ورجع داود ليبارك أهل بيته، فخرجت ميكال بنت شاول للقائه قائلة: «ما كان أعظم ملك إسرائيل اليوم، حين استعرض نفسه أمام عيون إماء خدامه، كما يستعرض أحد السفهاء نفسه».","6:21":"فأجابها داود: «إنما احتفلت في حضرة الرب الذي اختارني دون أبيك ودون أي من أهل بيته ليقيمني رئيسا على شعب الرب إسرائيل.","6:22":"وإني لأتصاغر دون ذلك وأكون وضيعا في عيني نفسي، ولكني أتمجد عند الإماء اللواتي ذكرتهن».","6:23":"ولم تنجب ميكال بنت شاول ولدا إلى يوم موتها.","7:1":"وبعد أن استقر الملك في قصره، وأراحه الرب من أعدائه المحيطين به،","7:2":"قال لناثان النبي: «انظر! أنا مقيم في بيت مصنوع من خشب أرز، بينما تابوت الرب ساكن في خيمة»","7:3":"فقال ناثان للملك: «قم واصنع كل ما تحدثك به نفسك، لأن الرب معك».","7:4":"ولكن في تلك الليلة قال الرب لناثان:","7:5":"«اذهب وقل لعبدي داود: لست أنت الذي تبني لي بيتا لإقامتي","7:6":"فمنذ أن أخرجت بني إسرائيل من مصر إلى هذا اليوم لم أسكن في بيت، بل كنت أتنقل من مكان إلى آخر في خيمة هي مسكن لي.","7:7":"وفي غضون تلك الحقبة التي سرت فيها مع جميع إسرائيل، هل سألت أحد قضاة إسرائيل الذين وليتهم رعاية شعبي قائلا: لماذا لم تبنوا لي بيتا من خشب الأرز؟","7:8":"والآن قل لعبدي داود: هذا ما يقوله الرب القدير: أنا أخذتك من المربض من رعاية الغنم لتكون رئيسا لشعبي إسرائيل،","7:9":"وعضدتك حيثما توجهت، أهلكت جميع أعدائك من أمامك، وجعلت لك شهرة عظيمة كشهرة عظماء الأرض.","7:10":"وأورثت شعبي إسرائيل أرضا معينة وثبته فيها، فسكن في أرضه آمنا، فلم يعد بنو الإثم قادرين على إذلاله كما جرى سابقا،","7:11":"وكما حدث منذ أن أقمت قضاة على شعبي إسرائيل لقد أرحتك من جميع أعدائك، وقد أخبرك الرب أنه سيثبت نسلك من بعدك.","7:12":"ومتى استوفيت أيامك ورقدت مع آبائك، فإنني أقيم بعدك من نسلك الذي يخرج من صلبك من أثبت مملكته.","7:13":"هو يبني بيتا لاسمي، وأنا أثبت عرش مملكته إلى الأبد.","7:14":"أنا أكون له أبا وهو يكون لي ابنا، إن انحرف أسلط عليه الشعوب الأخرى لأقومه بضرباتهم.","7:15":"ولكن لا أنزع رحمتي منه كما نزعتها من شاول الذي أزلته من طريقك.","7:16":"ويدوم بيتك ومملكتك إلى الأبد أمامي، فيكون عرشك ثابتا مدى الدهر».","7:17":"فأبلغ ناثان داود جميع هذا الكلام بمقتضى الرؤيا التي أعلنت له.","7:18":"فدخل الملك إلى خيمة الاجتماع ومثل أمام الرب قائلا: «من أنا يا سيدي ومن هي عائلتي حتى رفعتني إلى هذا المقام؟","7:19":"وكأن هذا الأمر صغر في عينيك يا سيدي الرب، فرحت تتعهد بالحفاظ على ذرية عبدك إلى زمن طويل. وهذا ما يتوق إليه قلب الإنسان؟","7:20":"وأي شيء آخر يمكن لداود أن يخاطبك به؟ فأنت تعرف حقيقة عبدك يا سيدي الرب.","7:21":"لقد أجريت هذه العظائم إكراما لكلمتك، وبموجب إرادتك، وأطلعت عليها عبدك.","7:22":"لذلك ما أعظمك أيها السيد الرب لأنه ليس لك نظير، وليس هناك إله غيرك حسب كل ما سمعناه بآذاننا.","7:23":"وأية أمة على الأرض تماثل شعبك إسرائيل الذي اخترته وافتديته ليكون لك شعبا ويذيع اسمك، وأجريت عظائم ومعجزات مذهلة، لتطرد من أمام شعبك الذي أنقذته من مصر، أمما مع آلهتها.","7:24":"وثبته لنفسك ليكون لك شعبا خاصا إلى الأبد، وأنت يا رب صرت لهم إلها.","7:25":"والآن أيها الرب الإله، احفظ إلى الأبد الوعود التي قطعتها لعبدك ولأهل بيته، وأوف بما نطقت به.","7:26":"وليتعظم اسمك إلى الأبد، فيقول البشر: حقا إن رب الجنود هو إله على إسرائيل. وليكن بيت عبدك داود ثابتا أمامك،","7:27":"لأنك أنت أيها الإله القدير، إله إسرائيل، قد أعلنت لعبدك قائلا: أقيم من صلبك ملوكا، لذلك رأى عبدك أن يرفع إليك هذه الصلاة.","7:28":"والآن يا سيدي الرب أنت هو الله، وكلامك حق، وقد وعدت عبدك بهذا الخير.","7:29":"فتعطف وبارك بيت عبدك ليثبت إلى الأبد أمامك، لأنك يا سيدي الرب قد وعدت، إذ ببركتك يتبارك بيت عبدك إلى الأبد».","8:1":"وبعد ذلك حارب داود الفلسطينيين وأخضعهم واستولى على عاصمتهم جت.","8:2":"وقهر أيضا الموآبيين وجعلهم يرقدون على الأرض في صفوف متراصة، وقاسهم بالحبل. فكان يقتل صفين ويستبقي صفا. فأصبح الموآبيون عبيدا لداود يدفعون له الجزية.","8:3":"وحين حاول هدد عزر بن رحوب، ملك صوبة أن يسترد سلطته على أعالي نهر الفرات هزمه داود،","8:4":"وأسر من جيشه ألفا وسبع مئة فارس وعشرين ألف راجل، وعرقب داود كل خيول المركبات باستثناء مئة مركبة.","8:5":"وعندما خف ملك آرام دمشق لنجدة هدد عزر ملك صوبة، قتل داود من جيشه اثنين وعشرين ألف رجل.","8:6":"وأقام داود حاميات عسكرية في آرام دمشق، وأصبح الآراميون تابعين لداود يدفعون له الجزية، وكان الرب ينصر داود حيثما توجه.","8:7":"واستولى داود على أتراس الذهب التي كان يرتديها قادة هدد عزر وحملها إلى أورشليم.","8:8":"كما نقل داود الملك من باطح ومن بيروثاي مدينتي هدد عزر كمية هائلة من النحاس.","8:9":"ولما علم توعي ملك حماة أن داود قد قضى على جيش هدد عزر،","8:10":"بعث ابنه يورام إلى الملك داود يستفسر عن سلامته، ويهنئه على انتصاره على هدد عزر، لأن هدد عزر كان يشن حروبا على توعي، وحمله هدايا من فضة وذهب ونحاس.","8:11":"فتقبلها داود الملك، ولكنه خصصها للرب مع ما خصصه من الفضة والذهب الذي حصل عليه من جميع الشعوب التي أخضعها","8:12":"من آرام، ومن موآب، ومن بني عمون، ومن الفلسطينيين ومن عماليق؛ وما غنمه من أسلاب هدد عزر ملك صوبة.","8:13":"وأصاب داود شهرة واسعة بعد رجوعه من القضاء على ثمانية عشر ألف أدومي في وادي الملح.","8:14":"وأقام عدة حاميات عسكرية في جميع أرجاء أدوم، فأصبح الأدوميون تابعين لداود. وكان الرب ينصر داود حيثما توجه.","8:15":"وملك داود على كل إسرائيل فكان يحكم بالحق والعدل لكل شعبه.","8:16":"وتولى يوآب ابن صروية قيادة الجيش، ويهوشافاط بن أخيلود منصب المسجل،","8:17":"وكان صادوق بن أخيطوب وأخيمالك بن أبياثار كاهنين، وسرايا كاتبا.","8:18":"كما ترأس بناياهو بن يهوياداع على الجلادين والسعاة، وصار أبناء داود مستشارين للملك.","9:1":"وتساءل داود: «هل بقي أحد من بيت شاول على قيد الحياة لأسدي إليه معروفا إكراما ليوناثان؟»","9:2":"وكان هناك عبد لبيت شاول يدعى صيبا، فاستدعوه ليمثل أمام داود، فسأله الملك: «هل أنت صيبا؟»","9:3":"فأجاب: «أنا هو عبدك». فقال الملك: «ألم يبق أحد بعد من ذرية شاول فأحسن إليه؟» فقال صيبا للملك: «بقي ابن ليوناثان أعرج الرجلين».","9:4":"فسأله الملك: «أين هو؟» فأجاب: «في بيت ماكير بن عميئيل، في لودبار».","9:5":"فأرسل الملك داود من أحضره من هناك.","9:6":"وعندما مثل مفيبوشث بن يوناثان بن شاول في حضرة داود خر على وجهه ساجدا. فقال داود: «يا مفيبوشث» فأجاب: «أنا عبدك».","9:7":"فقال له داود: «لا تخف، فإني مزمع أن أسدي إليك معروفا، إكراما ليوناثان أبيك، وأرد لك كل حقول شاول جدك، وتأكل دائما معي على مائدتي».","9:8":"فسجد مفيبوشث وقال: «من هو عبدك حتى تكرم كلبا ميتا مثلي؟»","9:9":"واستدعى الملك صيبا خادم شاول وقال له: «لقد وهبت حفيد سيدك كل ما كان يملكه شاول وأهل بيته.","9:10":"فعليك أنت وأبنائك وعبيدك أن تعملوا له في الأرض، وتفلحوها ليكون لحفيد سيدك رزق يعيش منه. أما مفيبوشث حفيد سيدك فيأكل دائما على مائدتي» وكان لصيبا خمسة عشر ابنا وعشرون عبدا.","9:11":"فأجاب صيبا: «سينفذ عبدك كل ما يأمر به مولاي الملك». وهكذا راح مفيبوشث يأكل على مائدة داود كأحد أولاد الملك.","9:12":"وكان لمفيبوشث ابن صغير يدعى ميخا، وصار جميع المقيمين في بيت صيبا في خدمة مفيبوشث","9:13":"فسكن مفيبوشث في أورشليم، لأنه كان يأكل دائما على مائدة الملك. وكان مصابا بعرج في رجليه كلتيهما.","10:1":"ثم مات ملك بني عمون، واعتلى العرش ابنه حانون.","10:2":"فقال داود في نفسه: «لأصنعن خيرا لحانون بن ناحاش كما صنع أبوه معي» فبعث داود وفدا ليعزيه في وفاة أبيه. وعندما بلغ وفد داود أرض بني عمون","10:3":"قال رؤساء بني عمون لسيدهم: «أتظن أن داود يستهدف إكرام أبيك في عينيك بإرساله هذا الوفد للتعزية؟ إنه لم يرسل هذا الوفد إلا لاستطلاع أحوال المدينة والتجسس عليها وقلبها».","10:4":"فقبض حانون على أعضاء وفد داود وحلق أنصاف لحاهم وقص ثيابهم إلى منتصف ظهورهم، ثم أطلقهم.","10:5":"ولما علم داود بالأمر أرسل من استقبلهم، لأن أعضاء الوفد اعتراهم خجل شديد. وأمرهم الملك أن يمكثوا في أريحا ريثما تنبت لحاهم ثم يرجعون.","10:6":"وعندما تبين العمونيون أن داود قد أضمر لهم البغضاء، استأجروا من آرام بيت رحوب آرام صوبا عشرين ألف راجل، ومن ملك معكة ألف رجل، ومن رجال طوب اثني عشر ألف رجل.","10:7":"فحين بلغ الخبر داود أرسل يوآب وسائر قواته الأبطال،","10:8":"فخرج بنو عمون واصطفوا للقتال عند مدخل باب المدينة، أما آراميو صوبا ورحوب ورجال طوب ومعكة فقد احتشدوا في الحقول.","10:9":"وعندما أدرك يوآب أنه محاصر بجبهتي قتال من أمام ومن خلف، انتخب من صفوة جيشه رجالا صفهم للقاء الآراميين،","10:10":"وعهد ببقية الجيش إلى أخيه أبيشاي، فصفهم هذا لمواجهة بني عمون.","10:11":"وقال يوآب: «إن تغلب علي الآراميون تسرع لنجدتي، وإن قوي عليك العمونيون أخف لإغاثتك.","10:12":"لتتشجع ولتتقو من أجل شعبنا ومن أجل مدن إلهنا، والرب يجري ما يشاء».","10:13":"وتقدم يوآب بقواته لمحاربة الآراميين فلاذوا بالفرار.","10:14":"وعندما شاهد العمونيون الآراميين يولون الأدبار، هربوا هم أيضا من أمام أبيشاي ودخلوا المدينة، فرجع يوآب عن بني عمون وعاد إلى أورشليم.","10:15":"وبعد أن رأى الآراميون أنهم قد انهزموا أمام جيش إسرائيل اجتمعوا معا.","10:16":"فأرسل هدد عزر واستدعى آراميي نهر الفرات، فتجمعوا في حيلام تحت قيادة شوبك رئيس جيش هدد عزر.","10:17":"فلما علم داود، حشد جيوشه واجتاز نهر الأردن حتى قدم إلى حيلام فالتقى الجيشان في حرب ضروس.","10:18":"وما لبث الآراميون أن اندحروا أمام الإسرائيليين، فقتلت قوات داود رجال سبع مئة مركبة، وأربعين ألف فارس. وأصيب شوبك رئيس الجيش ومات هناك.","10:19":"وحين أدرك جميع حلفاء هدد عزر أنهم اندحروا أمام الإسرائيليين، عقدوا صلحا معهم وأصبحوا تابعين لهم ولم يجرؤوا على نجدة بني عمون بعد ذلك.","11:1":"وفي ربيع العام التالي، في الموسم الذي اعتاد فيه الملوك الخروج للحرب، أرسل داود قائد جيشه يوآب على رأس قواته حيث هاجموا بني عمون وقهروهم، وحاصروا مدينة ربة، أما داود فمكث في أورشليم.","11:2":"وفي إحدى الأمسيات نهض داود عن سريره وأخذ يتمشى على سطح قصره، فشاهد امرأة ذات جمال أخاذ تستحم.","11:3":"فأرسل داود من يتحرى عنها. فأبلغه أحدهم: «هذه بثشبع بنت أليعام زوجة أوريا الحثي»،","11:4":"فبعث داود يستدعيها. فأقبلت إليه وضاجعها إذ كانت قد تطهرت من طمثها، ثم رجعت إلى بيتها.","11:5":"وحملت المرأة فأرسلت تبلغ داود بذلك.","11:6":"فوجه داود إلى يوآب قائلا: «أرسل إلي أوريا الحثي». فبعث به يوآب إلى داود.","11:7":"وحين مثل لدى داود استفسر منه عن سلامة يوآب والجيش وعن أنباء الحرب.","11:8":"ثم قال داود لأوريا: «امض إلى بيتك واغسل رجليك». فخرج أوريا من بيت الملك، وأرسل له هدية إلى بيته.","11:9":"غير أن أوريا لم يتوجه إلى بيته، بل نام مع رجال الملك عند باب القصر.","11:10":"فأخبروا داود قائلين: «لم يتوجه أوريا إلى بيته». فسأله داود: «ألم ترجع من سفر؟ فلماذا لم تمض إلى بيتك؟»","11:11":"فأجاب: «التابوت وجيش إسرائيل ويهوذا معسكرون في الخيام، وكذلك سيدي يوآب، وبقية قواد الملك مخيمون في العراء، فهل آتي أنا إلى بيتي لآكل وأشرب وأضاجع زوجتي؟ أقسم بحياتك، لن أفعل هذا الأمر».","11:12":"فقال داود لأوريا: «امكث هنا اليوم وغدا أطلقك». فمكث أوريا في أورشليم ذلك اليوم حتى صباح اليوم التالي.","11:13":"ولبى دعوة الملك، فأكل في حضرته وشرب حتى أسكره داود. ثم خرج عند المساء ليرقد في مضجعه إلى جوار رجال سيده، ولم يتوجه إلى بيته أيضا.","11:14":"وفي الصباح كتب داود رسالة إلى يوآب، بعث بها مع أوريا،","11:15":"جاء فيها: «اجعلوا أوريا في الخطوط الأولى حيث ينشب القتال الشرس، ثم تراجعوا من ورائه ليلقى حتفه».","11:16":"فعين يوآب أوريا في أثناء محاصرة المدينة، في أشد جبهات القتال ضراوة، حيث احتشد أبطال الأعداء.","11:17":"فاندفع رجال المدينة لمحاربة يوآب فمات بعض رجال داود ومنهم أوريا الحثي.","11:18":"فبعث يوآب رسولا ليطلع داود على أنباء الحرب،","11:19":"وأوصاه قائلا: «إن رأيت أن الملك بعد إبلاغه أنباء الحرب","11:20":"قد ثار غضبه وقال لك: لماذا اقتربتم من سور المدينة للقتال؟ أما علمتم أنهم يرمون بالسهام من فوق السور؟","11:21":"من صرع أبيمالك بن يربوشث؟ ألم ترمه امرأة بحجر رحى من على السور فمات في تاباص؟ لماذا اقتربتم من السور؟ فقل له: قد مات عبدك أوريا الحثي أيضا».","11:22":"فانطلق الرسول إلى داود وأطلعه على آخر أنباء الحرب التي كلفه بها يوآب.","11:23":"وقال: «لقد قوي علينا القوم وخرجوا لقتالنا في العراء، ولكننا انكفأنا عليهم وطاردناهم حتى بوابة المدينة.","11:24":"فرمى الرماة على عبيدك بالسهام، فقتل بعض ضباط الملك، ومات عبدك أوريا الحثي».","11:25":"فقال داود للرسول: «هذا ما تخبر به يوآب: لا يسوءنك هذا الأمر، فإن السيف يلتهم هذا وذاك. شدد حصارك على المدينة ودمرها. قل هذا لتشجيع يوآب».","11:26":"وعندما علمت زوجة أوريا أن زوجها قد قتل ناحت عليه.","11:27":"وحين انقضت فترة الحداد، أرسل داود وأحضرها إلى القصر وتزوجها وولدت ابنا ولكن الرب استاء من هذا الأمر الذي ارتكبه داود.","12:1":"وأرسل الرب ناثان إلى داود. وعندما وفد عليه قال له: «عاش رجلان في مدينة واحدة، أحدهما ثري والآخر فقير.","12:2":"وكان الغني يمتلك قطعان بقر وغنم كثيرة.","12:3":"وأما الفقير فلم يكن له سوى نعجة واحدة صغيرة، اشتراها ورعاها فكبرت معه ومع أبنائه، تأكل مما يأكل وتشرب من كأسه وتنام في حضنه كأنها ابنته.","12:4":"ثم نزل ضيف على الرجل الغني، فامتنع أن يذبح من غنمه ومن بقره ليعد طعاما لضيفه، بل سطا على نعجة الفقير وهيأها له».","12:5":"عندئذ احتدم غضب داود على الرجل الغني وقال لناثان: «حي هو الرب، إن الجاني يستوجب الموت،","12:6":"وعليه أن يرد للرجل الفقير أربعة أضعاف لأنه ارتكب هذا الذنب ولم يشفق».","12:7":"فقال ناثان لداود: «أنت هو الرجل! وهذا ما يقوله الرب إله إسرائيل: لقد اخترتك لتكون ملكا على إسرائيل وأنقذتك من قبضة شاول،","12:8":"ووهبتك بيت سيدك وزوجاته، ووليتك على بني إسرائيل ويهوذا. ولو كان ذلك قليلا لوهبتك المزيد.","12:9":"فلماذا احتقرت كلام الرب لتقترف الشر أمامه؟ قتلت أوريا الحثي بسيف العمونيين وتزوجت امرأته.","12:10":"لذلك لن يفارق السيف بيتك إلى الأبد، لأنك احتقرتني واغتصبت امرأة أوريا الحثي».","12:11":"واستطرد: «هذا ما يقوله الرب: سأثير عليك من أهل بيتك من ينزل بك البلايا، وآخذ نساءك أمام عينيك وأعطيهن لقريبك، فيضاجعهن في وضح النهار.","12:12":"أنت ارتكبت خطيئتك في السر، وأنا أفعل هذا الأمر على مرأى جميع بني إسرائيل وفي وضح النهار».","12:13":"فقال داود لناثان: «قد أخطأت إلى الرب». فقال ناثان: «والرب قد نقل عنك خطيئتك، فلن تموت.","12:14":"ولكن لأنك جعلت أعداء الرب يشمتون من جراء هذا الأمر، فإن الابن المولود لك يموت».","12:15":"وانصرف ناثان إلى بيته. وما لبث أن أصاب الرب الطفل الذي أنجبته أرملة أوريا الحثي لداود بمرض.","12:16":"فابتهل داود إلى الله من أجله، وأطال الصيام واعتصم بمخدعه وافترش الأرض.","12:17":"فراح وجهاء أهل بيته يحاولون إقناعه لينهض عن الأرض، فأبى ولم يأكل معهم طعاما.","12:18":"غير أن الطفل مات في اليوم السابع. فخاف رجال حاشية داود أن يخبروه، وقالوا: «عندما كان الولد حيا وحاولنا تعزيته لم يصغ إلينا. فكيف نقول له إن الولد مات؟ قد يؤذي نفسه!»","12:19":"وإذ شاهد داود رجال حاشيته يتهامسون، أدرك أن الولد قد مات، فسألهم: «هل توفي الولد؟» فأجابوا: «نعم».","12:20":"عندئذ نهض داود عن الأرض واغتسل وتطيب وبدل ثيابه ودخل إلى بيت الرب وصلى ساجدا، ثم عاد إلى قصره وطلب طعاما فأكل.","12:21":"فسأله رجال حاشيته: «كيف تتصرف هكذا؟ عندما كان الصبي حيا صمت وبكيت، ولكن ما إن مات حتى قمت وتناولت طعاما؟»","12:22":"فأجاب: «حين كان الطفل حيا صمت وبكيت لأني حدثت نفسي: من يعلم؟ ربما يرحمني الرب ويحيا الولد.","12:23":"أما الآن وقد مات، فلماذا أصوم؟ هل أستطيع أن أرده إلى الحياة؟ أنا ماض إليه، أما هو فلن يرجع إلي».","12:24":"ثم توجه داود إلى بثشبع وواساها وضاجعها، فولدت له ابنا دعاه سليمان. وأحب الرب الولد،","12:25":"وأمر النبي ناثان أن يسمى الولد يديديا (ومعناه محبوب الرب) لأن الرب أحبه.","12:26":"وهاجم يوآب ربة عمون واستولى على عاصمة المملكة،","12:27":"ثم بعث برسل إلى داود قائلا: «لقد حاربت ربة واستوليت على مصادر مائها،","12:28":"فالآن احشد بقية الجيش وتعال هاجم المدينة وافتتحها، لئلا أقهرها أنا فيطلقون اسمي عليها».","12:29":"فحشد داود كل الجيش وانطلق إلى ربة وهاجمها وافتتحها،","12:30":"وأخذ تاج ملكهم عن رأسه، ووزنه وزنة (نحو أربعة وثلاثين كيلو جراما) من الذهب والأحجار الكريمة، وتتوج به. كما استولى على غنائم وفيرة.","12:31":"واستعبد أهلها وفرض عليهم العمل بالمعاول والمناشير والفؤوس وأفران الطوب. وعامل جميع أهل مدن العمونيين بمثل هذه المعاملة. ثم عاد داود وسائر جيشه إلى أورشليم.","13:1":"وكان لأبشالوم بن داود أخت جميلة تدعى ثامار، فأحبها أخوها غير الشقيق أمنون.","13:2":"وعانى أمنون من سقم الحب، لأن ثامار أخته كانت عذراء وتعذر عليه تحقيق مأربه منها.","13:3":"وكان لأمنون صديق راجح العقل، هو ابن عمه، يوناداب بن شمعى،","13:4":"فسأله: «مالي أراك سقيما يا ابن الملك يوما بعد يوم؟ ألا تخبرني؟» فأجابه أمنون: «إني أحب ثامار أخت أبشالوم أخي».","13:5":"فقال يوناداب: «تمارض في سريرك. وعندما يجيء أبوك ليزورك قل له: دع ثامار أختي تأتي لتطعمني. دعها تعد الطعام أمامي فأرى ما تفعل وآكل من يدها».","13:6":"فاضطجع أمنون وتمارض، وقال لأبيه عندما جاء ليزوره: «دع ثامار تأتي لتصنع أمامي كعكتين، فآكل من يدها».","13:7":"فأرسل داود من يدعو ثامار من بيتها قائلا: «اذهبي إلى بيت أخيك أمنون واصنعي له طعاما».","13:8":"فمضت ثامار إلى بيت أخيها أمنون الراقد في سريره، فعجنت أمامه العجين وصنعت كعكا وخبزته.","13:9":"ثم أخذت المقلاة وسكبت الطعام أمامه. لكنه أبى أن يأكل قائلا: «أخرجوا كل من هنا». فانصرف جميع من عنده.","13:10":"ثم قال أمنون لثامار: «أحضري الطعام إلى السرير وأطعميني». فأحضرت ثامار الكعك الذي صنعته إلى أمنون أخيها الراقد في سريره.","13:11":"وما إن قدمته له حتى أمسكها وقال لها: «تعالي اضطجعي معي يا أختي».","13:12":"فأجابته: «لا يا أخي. لا تذلني. لأنه لا يقترف مثل هذا العمل الشنيع في إسرائيل. أرجوك لا ترتكب هذه القباحة،","13:13":"إذ كيف أواري عاري؟ أما أنت فتكون بتصرفك هذا كواحد من السفهاء في إسرائيل. خاطب الملك بشأني فإنه لن يمنعني من الزواج منك».","13:14":"فأبى أن يستمع لتوسلاتها، بل تغلب عليها واغتصبها.","13:15":"ثم تحول حب أمنون لثامار إلى بغض شديد فاق محبته لها. وقال لها: «قومي انطلقي».","13:16":"فأجابت: «لا! إن طردك إياي جريمة أشنع من الجريمة التي اقترفتها». لكنه أبى أن يسمع لها،","13:17":"واستدعى خادمه الخاص وقال: «اطرد هذه المرأة خارجا، وأغلق الباب وراءها».","13:18":"فطردها الخادم وأغلق الباب خلفها. وكانت ثامار ترتدي ثوبا ملونا كعادة بنات الملوك العذارى في تلك الأيام،","13:19":"فمزقت الثوب الملون وعفرت رأسها بالرماد ووضعت عليه يدها ومضت باكية.","13:20":"وعندما رآها أخوها أبشالوم سألها: «هل اغتصبك أمنون؟ اسكتي الآن يا أختي، فإنه أخوك ولا تحملي وزر هذا الأمر في قلبك». فأقامت ثامار في بيت أخيها أبشالوم في عزلة وحزن.","13:21":"ونما الخبر إلى الملك داود فاغتاظ جدا.","13:22":"أما أبشالوم فلم يخاطب أمنون بخير أو شر، لكنه أضمر له بغضا شديدا لأنه انتهك حرمة أخته ثامار.","13:23":"وبعد ذلك بعامين، وجه أبشالوم دعوة لجميع أبناء الملك لحضور جز غنمه في بعل حاصور عند أفرايم.","13:24":"وعندما مثل أبشالوم في حضرة أبيه قال له: «هذا موسم جز غنم عبدك، فليذهب الملك مع رجال حاشيته برفقة عبده».","13:25":"فأجاب الملك أبشالوم: «لا يا ابني. لا نذهب كلنا لئلا نكون عبئا عليك». ورغم إلحاح أبشالوم، اعتذر أبوه وباركه.","13:26":"فقال أبشالوم: «إذا دع أخي أمنون يذهب معنا» فقال الملك: «ولماذا يذهب أمنون معك؟»","13:27":"فألح عليه أبشالوم حتى رضي أن يذهب أمنون وأبناء الملك مع أبشالوم.","13:28":"وأوصى أبشالوم رجاله: «متى ذهبت الخمر بعقل أمنون وقلت لكم اضربوا أمنون واقتلوه، فلا تخافوا. ألست أنا الذي أمرتكم بذلك؟ تشجعوا وتصرفوا كأبطال».","13:29":"فنفذ رجال أبشالوم أوامره وقتلوا أمنون، فهب جميع أبناء الملك وامتطوا بغالهم وهربوا.","13:30":"وفيما هم في الطريق بلغ الخبر داود وقيل له: «قتل أبشالوم جميع أبناء الملك ولم يسلم منهم أحد».","13:31":"فقام الملك ومزق ثيابه وانطرح على الأرض، يحيط به جميع رجال حاشيته ممزقي الثياب.","13:32":"ولكن يوناداب بن شمعي أخي داود قال: «لا يظن سيدي أنهم قتلوا جميع أبناء الملك. إنما أمنون وحده هو الذي مات، لأن أبشالوم قد أضمر له هذا الشر منذ أن اغتصب أخته ثامار.","13:33":"فلا يخالج قلب الملك أن جميع أبنائه قد قتلوا، إنما أمنون وحده هو الذي اغتيل».","13:34":"وهرب أبشالوم. وشاهد الرقيب المكلف جمعا غفيرا قادما في الطريق الموازي للجبل،","13:35":"فقال يوناداب للملك: «ها أبناء الملك قد جاءوا. تماما كما قال عبدك».","13:36":"وما إن فرغ من حديثه حتى جاء بنو الملك نائحين، وكذلك بكى الملك ورجال حاشيته بكاء مرا.","13:37":"وعندما هرب أبشالوم لجأ إلى تلماي بن عميهود ملك جشور. وناح داود على أمنون طوال أيام المناحة.","13:38":"ومكث أبشالوم في جشور ثلاث سنوات.","13:39":"وما لبث أن تعزى داود عن أمنون المتوفى، فاشتاقت نفسه للقاء أبشالوم.","14:1":"وعلم يوآب بن صروية أن قلب الملك متشوق لأبشالوم،","14:2":"فاستدعى يوآب من تقوع امرأة حكيمة وقال لها: «تظاهري بالحزن، وارتدي ثياب الحداد، ولا تتطيبي، وتصرفي كامرأة قضت أياما طويلة غارقة في أحزانها على فقيد.","14:3":"وادخلي لمقابلة الملك، وكلميه بما أسره إليك». ولقنها يوآب ما تقول.","14:4":"ومثلت المرأة التقوعية أمام الملك، وخرت على وجهها إلى الأرض وسجدت قائلة: «أغثني أيها الملك»","14:5":"فسألها الملك: «ما شأنك؟» فأجابت: «أنا أرملة، مات رجلى","14:6":"مخلفا لي ابنين. فتخاصما في الحقل من غير أن يكون هناك من يفرق بينهما. فضرب أحدهما الآخر وقتله.","14:7":"وها هي العشيرة قاطبة قد قامت تطالبني بتسليم القايل لمعاقبته جزاء له على قتل أخيه وبذلك يقضون على الوارث. وهكذا يطفئون أملي الذي بقي لي، ويمحون اسم زوجي وذكره من على وجه الأرض».","14:8":"فقال الملك للمرأة: «امضي إلى بيتك وأنا أصدر قرارا في أمرك».","14:9":"فأجابت المرأة: «ليقع اللوم علي وعلى بيت أبي، أما الملك وعرشه فهما بريئان من كل شائبة».","14:10":"فقال الملك: «إذا اعترض عليك أحد فأحضريه إلي فلا يعود يسيء إليك».","14:11":"فقالت المرأة: «احلف لي باسم الرب إلهك أن تمنع طالب الدم من إراقة مزيد من الدماء لئلا يهلك ابني». فأجابها: «حي هو الرب إنه لن تسقط شعرة من رأس ابنك إلى الأرض».","14:12":"فقالت المرأة: «دع جاريتك تقول كلمة لسيدي الملك» فقال: «تكلمي».","14:13":"قالت المرأة: «إذن، لماذا ارتكبت هذا الأمر في حق شعب الله؟ ألا يدين الملك نفسه عندما يصدر مثل هذا الحكم لأنه لم يرد ابنه من منفاه؟","14:14":"لأننا لابد أن نموت ونكون مثل المياه المتسربة في شقوق الأرض التي يتعذر جمعها. ولكن الله لا يستأصل نفسا بل يفكر بشتى الطرق حتى لا يقطع عنه منفيه.","14:15":"وها أنا الآن قد جئت لأخاطب سيدي الملك بهذا الأمر لأن الشعب أخافني. فقلت: سأخاطب الملك لعله يتقبل طلب جاريته.","14:16":"لأن الملك قد يوافق على إنقاذ جاريته من يد الرجل الذي يحاول أن يقضي علي وعلى ابني ويستولي على الميراث الذي وهبنا إياه الله.","14:17":"وقالت جاريتك: لتحمل كلمة سيدي الملك عزاء لنفسي، لأن سيدي الملك هو كملاك الله في التمييز بين الخير والشر، والرب إلهك يكون معك».","14:18":"فقال الملك للمرأة: «لدي ما أسألك عنه فلا تكتمي الجواب عني». فأجابت: «ليتكلم سيدي الملك».","14:19":"فسألها: «هل ليوآب يد في كل هذا الأمر؟» فأجابت: «لتحي نفسك يا سيدي الملك! إن أحدا لا يقدر أن يراوغ في أمر سيدي الملك. نعم إن عبدك يوآب هو أوصاني ولقنني كل ما نطقت به.","14:20":"وقد قام يوآب بهذا الأمر لإحداث تغيير في الوضع الراهن. إن سيدي يتمتع بحكمة مماثلة لحكمة ملاك الله، وعالم بما يحدث في البلاد».","14:21":"فقال الملك ليوآب: لقد استقر رأيي على تنفيذ هذا الأمر. فاذهب الآن وأحضر الفتى أبشالوم».","14:22":"فانحنى يوآب بوجهه إلى الأرض وسجد وبارك الملك قائلا: «اليوم علم عبدك أني قد حظيت برضاك يا سيدي الملك، إذ استجاب الملك لطلب عبده».","14:23":"ثم انطلق يوآب إلى جشور وأحضر أبشالوم إلى أورشليم.","14:24":"فقال الملك: «لينصرف إلى بيته ولا ير وجهي». فمضى أبشالوم إلى بيته ولم يمثل في حضرة الملك.","14:25":"ولم يكن في كل إسرائيل رجل وسيم المحيا، يحظى بالإعجاب كأبشالوم الذي خلا من كل عيب من قمة الرأس إلى أخمص القدم.","14:26":"وكان يقص شعر رأسه مرة في كل عام لأنه كان يثقل عليه، إذ كان يزن مئتي شاقل (نحو كيلو جرامين ونصف).","14:27":"وأنجب أبشالوم ثلاثة بنين وبنتا واحدة اسمها ثامار، كانت تتمتع بقسط وافر من الجمال.","14:28":"ومكث أبشالوم في أورشليم سنتين من غير أن يحظى بالمثول في حضرة الملك","14:29":"فاستدعى يوآب ليتشفع له عند أبيه، فلم يشأ يوآب أن يأتي إليه. ثم أرسل إليه ثانية، فأبى أن يأتي أيضا.","14:30":"عندئذ قال أبشالوم لرجاله: «ليوآب حقل شعير مجاور لحقلي، فاذهبوا وأحرقوه». فقام رجال أبشالوم بإحراق الحقل بالنار.","14:31":"فأقبل يوآب إلى أبشالوم في بيته قائلا: «لماذا أحرق رجالك حقلي بالنار؟»","14:32":"فأجاب أبشالوم: «أرسلت طالبا إليك أن تأتي إلى هنا لأوفدك إلى الملك لتسأله لماذا استدعاني من جشور خير لي لو بقيت هناك. إني أود أن أمثل في حضرة الملك، فإن كنت مذنبا فليقتلني».","14:33":"فمضى يوآب إلى الملك وأبلغه كلام أبشالوم. فاستدعى الملك أبشالوم، فجاء هذا إليه وسجد أمامه، فقبل الملك أبشالوم.","15:1":"بعد ذلك اتخذ أبشالوم لنفسه مركبة وخيلا واستأجر خمسين رجلا يجرون أمامه.","15:2":"وكان يستيقظ مبكرا صباح كل يوم ويقف إلى جوار طريق بوابة المدينة، ويدعو إليه كل صاحب دعوى يقصد الملك ليعرض عليه قضيته، فيسأله: «من أية مدينة أنت؟» فيجيب: «عبدك ينتمي إلى أحد أسباط إسرائيل».","15:3":"فيقول أبشالوم له: «إن دعواك حق وقويمة، ولكن لا يوجد مندوب عن الملك ليستمع إليك».","15:4":"ثم يقول أبشالوم: «لو صرت قاضيا في الأرض لكنت أنصف كل إنسان له خصومة أو دعوى».","15:5":"وكان إذا تقدم أحد ليسجد له، يمد يده وينهضه ويقبله.","15:6":"وظل أبشالوم يفعل هذا الأمر مع كل قادم بقضية إلى الملك، حتى تمكن من اكتساب قلوب رجال إسرائيل.","15:7":"وبعد انقضاء أربع سنوات قال أبشالوم للملك: «دعني أنطلق إلى حبرون لأوفي نذري الذي نذرته للرب.","15:8":"فقد نذر عبدك، عندما كنت مقيما في جشور في آرام، أنه إن ردني الرب إلى أورشليم فإني أقدم له ذبيحة».","15:9":"فقال الملك له: «اذهب بسلام». فقام ومضى إلى حبرون.","15:10":"وبث أبشالوم جواسيس في أوساط جميع أسباط إسرائيل قائلا: «إن سمعتم نفير البوق، فقولوا: قد ملك أبشالوم في حبرون».","15:11":"ورافق أبشالوم مئتا رجل من أورشليم لبوا دعوته عن طيب نية غير عالمين بشيء.","15:12":"وفي أثناء تقريبه ذبائح، استدعى أبشالوم أخيتوفل الجيلوني مشير داود، من بلدته جيلوه. وتفاقمت الفتنة وازداد التفاف الشعب حول أبشالوم.","15:13":"فجاء مخبر قال لداود: «إن قلوب رجال إسرائيل قد مالت نحو أبشالوم».","15:14":"فقال داود لرجاله الملتفين حوله في أورشليم: «قوموا بنا نهرب، لأنه لا نجاة لنا من أبشالوم. أسرعوا في الهرب لئلا يفوت الوقت، ويدركنا أبشالوم ويدمر المدينة»","15:15":"فأجابه رجاله: «نحن طوع أمرك في كل ما تشير به».","15:16":"فخرج الملك وسائر أهل بيته، ولم يترك سوى عشر محظيات لحراسة القصر.","15:17":"وتوقف الملك والشعب السائر في إثره عند آخر بيت في طرف المدينة.","15:18":"وأخذ رجاله يمرون أمامه من ضباط وحرس خاص، ثم ست مئة رجل من الجتيين الذين تبعوه من جت.","15:19":"فقال الملك لقائدهم إتاي الجتي: «لماذا تذهب أنت أيضا معنا؟ ارجع وأقم مع الملك الجديد لأنك غريب ومنفي أيضا من وطنك.","15:20":"لقد جئت بالأمس القريب، فهل أجعلك اليوم تتشرد معنا، مع أنني لا أدري إلى أين أذهب؟ ارجع وعد بقومك، ولترافقك الرحمة والحق».","15:21":"ولكن إتاي أجاب الملك: «حي هو الرب وحي هو سيدي الملك، أنه حيثما يتوجه سيدي الملك، سواء كان للحياة أم للموت، يتوجه عبدك أيضا».","15:22":"فقال داود لإتاي: «تعال، واعبر معنا». فعبر إتاي الجتي وجميع أصحابه وسائر الأطفال الذين كانوا معه.","15:23":"وراح أهالي الأرض يبكون بصوت مرتفع فيما كان الملك ومن معه من الشعب يجتازون في وادي قدرون في طريقهم نحو الصحراء.","15:24":"وجاء صادوق أيضا ومعه جميع اللاويين حاملين تابوت عهد الرب، ووضعوه إلى جانب الطريق. وأصعد أبياثار ذبائح حتى انتهى جميع الشعب من اجتياز المدينة.","15:25":"وقال الملك لصادوق: «أرجع تابوت الله إلى المدينة، فإنني إن حظيت برضى الرب فإنه يعيدني فأرى التابوت ومسكنه.","15:26":"وإن لم أستحوذ على رضاه وقال: «إني لم أسر بك، فليفعل بي ما يطيب له».","15:27":"واستطرد الملك قائلا لصادوق الكاهن: «ألست أنت رائيا؟ هيا ارجع إلى المدينة بسلام أنت وأخيمعص ابنك ويوناثان بن أبياثار. خذا ابنيكما معكما.","15:28":"أما أنا فسأمكث منتظرا عند مخاوض النهر في الصحراء ريثما يصلني منكم خبر».","15:29":"فأرجع صادوق وأبياثار تابوت الله إلى أورشليم وأقاما هناك.","15:30":"أما داود فاستمر يرتقي جبل الزيتون باكيا مغطى الرأس حافي القدمين. وغطى جميع الشعب الذي معه رؤوسهم وارتقوا مسالك الجبل باكين.","15:31":"وقيل لداود إن أخيتوفل بين المتمردين الذين انضموا إلى أبشالوم. فصلى داود: «حمق يا رب مشورة أخيتوفل».","15:32":"عندما وصل داود إلى قمة الجبل سجد للرب، ثم شاهد حوشاي الأركي في انتظاره، ممزق الثياب معفر الرأس بالتراب،","15:33":"فقال له داود: «إذا جئت معي تصبح عبئا علي،","15:34":"ولكن إذا رجعت إلى المدينة وقلت لأبشالوم: أنا أكون خادما لك أيها الملك، فقد خدمت أباك منذ زمن، وها أنا الآن خادم لك، فإنك بذلك تبطل لي مشورة أخيتوفل.","15:35":"وستجد معك صادوق وأبياثار الكاهنين فأخبرهما بكل ما تسمعه في مجلس أبشالوم","15:36":"فيرسلا ابنيهما أخيمعص ويوناثان ليبلغاني بكل ما سمعاه».","15:37":"فعاد حوشاي مستشار داود إلى المدينة بينما كان أبشالوم يدخلها.","16:1":"وعندما عبر داود قمة الجبل لاقاه صيبا خادم مفيبوشث بحمارين محملين بمئتي رغيف خبز ومئة عنقود زبيب ومئة قرص تين وزق خمر.","16:2":"فقال الملك لصيبا: «لمن كل هذا؟» فأجاب صيبا: «الحماران لركوب عائلة الملك، والخبز والتين ليأكلها الرجال، والخمر لمن أعيا في الصحراء».","16:3":"فسأله الملك: «وأين حفيد سيدك؟» فأجاب صيبا: «هو مقيم في أورشليم لأنه حدث نفسه قائلا: اليوم يرد لي بيت إسرائيل مملكة جدي».","16:4":"فقال الملك لصيبا: «لقد وهبتك كل ما يمتلكه مفيبوشث». فقال صيبا: «إنني أنحني أمامك بخضوع، لعلني أحظى برضى سيدي الملك».","16:5":"وعندما وصل الملك داود إلى بحوريم خرج رجل من هناك ينتمي إلى عشيرة شاول، يدعى شمعي بن جيرا، وراح يكيل له الشتائم،","16:6":"ورشق داود ورجاله والشعب الذي معه والأبطال الملتفين عن يمينه ويساره بالحجارة.","16:7":"وهو يردد في شتائمه: «اخرج! اخرج يا رجل الدماء ورجل بليعال!","16:8":"لقد رد الرب عليك كل ما سفكته من دماء بيت شاول الذي ملكت عوضا عنه، وقد سلم الرب المملكة إلى أبشالوم ابنك. وها أنت غارق في شر أعمالك لأنك رجل دماء».","16:9":"فقال أبيشاي ابن صروية للملك: «لماذا يشتم هذا الكلب الميت سيدي الملك؟ دعني أهجم عليه فأقطع رأسه».","16:10":"فقال الملك: «ليس هذا من شأنكم يا بني صروية. دعوه يشتم لأن الرب قال له اشتم داود. فمن يقدر أن يسأل: لماذا تفعل هذا؟»","16:11":"وقال الملك لأبيشاي وسائر رجاله: «هوذا ابني الذي خرج من صلبي يسعى لقتلي، فكم بالحري هذا البنياميني. دعوه يشتم لأن الرب أمره بشتمي.","16:12":"لعل الرب ينظر إلى مذلتي، ويكافئني خيرا عوض شتائمه في هذا اليوم».","16:13":"وتابع داود ورجاله المسير في الطريق، ولكن شمعي ظل يمشي بمحاذاتهم على الجانب الآخر من الجبل وهو يكيل لهم الشتائم ويرشقهم بالحجارة ويذري عليهم التراب.","16:14":"وعندما وصل الملك والشعب الذي معه ضفاف الأردن كان الإعياء قد أصابهم، فاستراحوا هناك.","16:15":"أما أبشالوم وأتباعه من رجال إسرائيل، وأخيتوفل، فقد دخلوا أورشليم.","16:16":"وجاء حوشاي الأركي مستشار داود إلى أبشالوم هاتفا: «ليحي الملك! ليحي الملك!»","16:17":"فقال له أبشالوم: «أبهذه الطريقة تكافئ صديقك؟ لماذا لم تذهب معه؟»","16:18":"فأجاب: «لا، إنني أخدم وأقيم مع من اختاره الرب وهذا الشعب وكل رجال إسرائيل.","16:19":"ثم من أخدم؟ ألست أخدم ابنه؟ فكما خدمت في حضرة أبيك كذلك أخدم بين يديك».","16:20":"وسأل أبشالوم أخيتوفل: «أشيروا ماذا نفعل؟»","16:21":"فأجاب أخيتوفل: «ادخل وضاجع محظيات أبيك اللواتي تركهن للمحافظة على القصر، فيسمع جميع بني إسرائيل أنك قد صرت مكروها لدى أبيك، فتتشدد أيدي مناصريك».","16:22":"فنصبوا لأبشالوم الخيمة على السطح، ودخل لمضاجعة محظيات أبيه على مرأى جميع الإسرائيليين.","16:23":"وكانت مشورات أخيتوفل التي يسديها في تلك الأيام تحظى بقبول داود وأبشالوم لأنها كانت في اعتبارهما كأنها صادرة عن فم الله.","17:1":"وقال أخيتوفل لأبشالوم: «دعني أختار اثني عشر ألف رجل لأقوم وأتعقب بهم داود هذه الليلة،","17:2":"فأهاجمه وهو متعب خائر القوى، فأثير الذعر بين رجاله، فينفضون من حوله، وأقتل الملك وحده.","17:3":"وأرد جميع الشعب إليك، لأن موت الرجل الذي تطلبه معناه رجوع الجميع للالتفاف حولك، ولا ينال الأذى أي واحد من الناس».","17:4":"فاستحسن أبشالوم وقادة بني إسرائيل هذا الرأي.","17:5":"غير أن أبشالوم قال: «استدعوا حوشاي الأركي لنستمع إلى ما يرتئي».","17:6":"فلما أقبل حوشاي أطلعه أبشالوم على رأي أخيتوفل ثم سأله: «أنعمل برأيه أم لا؟ تكلم أنت».","17:7":"فأجاب حوشاي: «مشورة أخيتوفل ليست صائبة هذه المرة»،","17:8":"ثم أضاف: «أنت تعلم أن أباك ورجاله هم أبطال يعصف بهم غضب جامح كدبة متوحشة مثكل، وأن أباك رجل قتال متمرس لا يبيت مع قواته.","17:9":"ولعله الآن مختبئ في خندق أو مكان آخر. وما إن يقتل بعض رجالك في بدء الحرب ويذيع خبرهم حتى يشيع أن جيش أبشالوم قد كسر،","17:10":"فيذوب قلب من هو في شجاعة الأسد من رجالك، لأن جميع بني إسرائيل يعلمون أن أباك جبار حرب، وأن رجاله أبطال أقوياء.","17:11":"لهذا أقترح أن تجند جيش إسرائيل كله من دان إلى بئر سبع، فيكون عدده كرمل البحر في الكثرة، وتقودهم أنت إلى المعركة.","17:12":"ثم نهاجم أباك حيث هو معسكر، ونسقط عليه كتساقط الندى على الأرض، فنقضي عليه وعلى جميع رجاله ولا يسلم أحد ممن معه.","17:13":"وإذا لجأ إلى مدينة يحاصر جميع إسرائيل تلك المدينة، ويجرونها بحبال إلى الوادي حتى لا يبقى لها أثر».","17:14":"فقال أبشالوم وسائر رجال إسرائيل: «إن رأي حوشاي الأركي أفضل من رأي أخيتوفل». لأن الرب أراد أن يبطل مشورة أخيتوفل الصائبة لكي يحل الشر بأبشالوم.","17:15":"وأبلغ حوشاي صادوق وأبياثار الكاهنين ما أشار به أخيتوفل على أبشالوم وعلى شيوخ إسرائيل، كما أطلعهما على ما أشار هو به عليهم وقال:","17:16":"«والآن أسرعا بإبلاغ داود وقولا له: لا تبت الليلة في سهول الصحراء، بل اعبر النهر، لئلا يتم ابتلاع الملك وجميع الشعب الذي معه».","17:17":"وكان يوناثان وأخيمعص منتظرين عند روجل متواريين عن أعين الرقباء. فانطلقت جارية وأخبرتهما بما يجري. وإذ كانا ماضيين لإبلاغ داود","17:18":"شاهدهما غلام وأخبر أبشالوم، فأسرعا يختبئان في بيت رجل في بحوريم في بئر في فناء داره.","17:19":"وأخذت زوجة الرجل غطاء ووضعته على فم البئر، ونثرت عليه حبوبا لتجف، فلم يشك أحد أنهما في داخل البئر.","17:20":"فجاء رجال أبشالوم إلى البيت وسألوا المرأة: «أين أخيمعص ويوناثان؟» فأجابت: «قد اجتازا الجدول وذهبا». وبعد أن أخفقوا في العثور عليهما رجعوا إلى أورشليم.","17:21":"وبعد ذهاب أعوان أبشالوم خرجا من البئر ومضيا وقالا للملك داود: «قوموا مسرعين واجتازوا النهر، لأن هكذا أشار أخيتوفل ضدكم».","17:22":"فهب داود وجميع من معه من الشعب واجتازوا نهر الأردن. وما إن انبلج الصباح حتى كان الجميع قد عبروا إلى ضفة النهر الأخرى.","17:23":"وعندما رأى أخيتوفل أن مشورته لم يعمل بها، ركب حماره وتوجه إلى بيته في مسقط رأسه، ثم نظم شؤون عائلته، وخنق نفسه فمات، ودفن في قبر أبيه.","17:24":"فوصل داود محنايم، كما اجتاز أبشالوم الأردن مع جميع رجال إسرائيل.","17:25":"وعين أبشالوم عماسا بدل يوآب قائدا للجيش. وكان عماسا ابن رجل يدعى يثرا الإسرائيلي الذي تزوج من أبيجايل بنت ناحاش، أخت صروية أم يوآب.","17:26":"وعسكر أبشالوم والإسرائيليون في أرض جلعاد","17:27":"وما إن وصل داود إلى محنايم حتى جاء شوبي بن ناحاش من ربة بني عمون، وماكير بن عميئيل من لودبار، وبرزلاي الجلعادي من روجليم،","17:28":"وقدموا فرشا وطسوسا وآنية خزف وقمحا وشعيرا ودقيقا وفريكا وفولا وعدسا وحمصا مشويا،","17:29":"وعسلا وزبدة وغنما وجبن بقر، لداود وللشعب الذي معه ليأكلوا قائلين: «لابد أن الشعب جائع وعطشان وخائر في الصحراء».","18:1":"وأحصى داود جيشه وعين عليهم قادة ألوف ومئات،","18:2":"ثم قسمهم إلى ثلاث فرق، جعل يوآب على واحدة منها، وأبيشاي ابن صروية أخا يوآب على الثانية، وإتاي الجتي على الفرقة الثالثة. وقال الملك لرجاله: «إني أيضا أخرج معكم».","18:3":"لكن الشعب قال: «لا تخرج معنا، لأننا إذا انهزمنا فإنهم لا يبالون بنا. وإذا مات نصفنا فلا يكترثون بنا أيضا. أما أنت فإنك تعادل عشرة آلاف منا، ومن الأفضل أن تمكث في المدينة وتسعفنا بنجدة إن دعا الأمر».","18:4":"فأجابهم الملك: «سأفعل ما يروق لكم». ووقف الملك إلى جوار بوابة المدينة يشيع مئات وألوف الجنود الخارجين للقتال.","18:5":"وأوصى الملك يوآب وأبيشاي وإتاي قائلا: «ترفقوا من أجلي بالفتى أبشالوم»، وسمع الجنود حين أوصى الملك كل قادته بأبشالوم.","18:6":"وانطلق الجيش إلى السهل لمحاربة إسرائيل، فدارت معركة في غابة أفرايم،","18:7":"انتهت بهزيمة جيش إسرائيل أمام قوات داود، وقتل منهم عشرون ألفا في مجزرة ذلك اليوم.","18:8":"واتسعت رقعة القتال، وافترست الغابة من الجيش أكثر من الذين افترسهم السيف في ذلك اليوم.","18:9":"وفي أثناء المعركة التقى أبشالوم ببعض رجال داود، وكان يركب آنئذ على بغل مر به تحت شجرة بلوط ضخمة ذات أغصان كثيفة متشابكة، فعلق شعره بأحد فروعها، ومر البغل من تحته وتركه متدليا بين السماء والأرض.","18:10":"فرآه رجل وأخبر يوآب: «رأيت أبشالوم معلقا بشجرة البلوط».","18:11":"فقال له يوآب: «رأيته معلقا ولم تقتله؟! لو فعلت، لأعطيتك عشرة قطع من الفضة، وحزام المحارب».","18:12":"فأجاب الرجل: «ولو أعطيتني ألفا من الفضة لما كنت أمد يدي إلى ابن الملك، لأن الملك أوصاك على مسمع منا أنت وأبيشاي وإتاي قائلا: ليحرص كل واحد منكم على حياة أبشالوم،","18:13":"ولو قتلت ابنه لكنت قد ارتكبت جناية في حق الملك الذي لا تخفى عليه خافية، ولكنت أنت نفسك وقفت ضدي».","18:14":"فقال يوآب: «لا يمكنني أن أصبر هكذا أمامك» وأخذ بيده ثلاثة سهام أنشبها في قلب أبشالوم، وهو ما برح حيا معلقا بشجرة البلوط.","18:15":"ثم أحاط بالشجرة عشرة غلمان، حاملي سلاح يوآب، وأجهزوا على أبشالوم فمات.","18:16":"ونفخ يوآب بالبوق فارتد جيش داود عن تعقب الإسرائيليين لأن يوآب حال دون ذلك.","18:17":"وأنزلوا أبشالوم وطرحوه في الغابة في حفرة عميقة، وأهالوا عليه رجمة كبيرة جدا من الحجارة. وهرب كل جندي من جيش إسرائيل إلى بيته.","18:18":"وكان أبشالوم قد أقام لنفسه في أثناء حياته نصبا تذكاريا في وادي الملك، لأنه قال: «ليس لي ابن يحمل اسمي من بعدي». ومازال هذا النصب معروفا بنصب أبشالوم إلى هذا اليوم.","18:19":"وقال أخيمعص بن صادوق ليوآب: «دعني أهرع لأبشر الملك أن الله قد انتقم له من أعدائه».","18:20":"فأجابه يوآب: «لا، لست أنت الذي تحمل بشارة في هذا اليوم، دعها لفرصة أخرى إذ لا بشارة في هذا اليوم لأن الميت هو ابن الملك».","18:21":"وقال يوآب لرجل كوشي: «اذهب وأبلغ الملك بما شاهدت». فسجد الكوشي ليوآب ومضى مسرعا.","18:22":"وألح أخيمعص بن صادوق على يوآب قائلا: «مهما حدث، دعني أجري وراء الكوشي أيضا». فقال يوآب: «لماذا تجري أنت يا ابني، ولست تحمل بشارة تكافأ عليها؟»","18:23":"فقال له: «مهما كان الأمر دعني أجري». فأذن له، فجرى أخيمعص في طريق الغور وسبق الكوشي.","18:24":"وبينما كان داود جالسا في الساحة الفاصلة بين البوابة الخارجية والبوابة الداخلية طلع الرقيب إلى السور فوق سطح الباب، وتلفت حوله وإذا به يرى رجلا يركض وحده،","18:25":"فأبلغ الرقيب الملك، فقال الملك: «إن كان وحده فهو حامل بشرى». وفي أثناء اقتراب الرسول","18:26":"رأى الرقيب رجلا آخر يركض، فقال للبواب: «هوذا رجل آخر يجري وحده». فقال الملك: «وهذا أيضا مبشر».","18:27":"وعاد الرقيب يقول: «إني أرى عدو الأول كعدو أخيمعص بن صادوق». فقال الملك: «هذا رجل صالح يحمل بشرى سارة».","18:28":"وعندما وصل أخيمعص هتف: «سلام للملك» وسجد أمامه إلى الأرض ثم قال: «تبارك الرب إلهك الذي أظفرك بالقوم الذين تمردوا على سيدي الملك».","18:29":"فسأل الملك: «أسالم الفتى أبشالوم؟» فأجاب أخيمعص: «حين أرسلني إليك عبدك يوآب رأيت هناك جلبة لم أدرك دواعيها».","18:30":"فقال له الملك: «تنح جانبا وانتظر هنا». فتنحى ووقف ينتظر.","18:31":"وإذا بالكوشي مقبل قائلا: «بشرى لسيدي الملك، لأن الرب قد انتقم لك اليوم من جميع الثائرين عليك».","18:32":"فسأل الملك الكوشي: «أسالم الفتى أبشالوم؟» فأجابه: «ليكن أعداء سيدي الملك وجميع من ثار عليك عدوانا كالفتى أبشالوم».","18:33":"فارتعش الملك وصعد إلى علية البوابة باكيا يذرع أرض الحجرة قائلا: «يا ابني، يا ابني أبشالوم. يا ليتني مت عوضا عنك يا أبشالوم يا ابني. آه يا ابني».","19:1":"وقيل ليوآب: «هوذا الملك يبكي وينوح على أبشالوم».","19:2":"فتحول النصر في ذلك اليوم لدى جميع الجيش إلى مناحة، إذ شاع بينهم أن الملك قد حزن جدا على مصرع ابنه.","19:3":"فتسلل أفراد الجيش عائدين إلى المدينة كما يتسلل قوم لحق بهم عار الهزيمة.","19:4":"وأخفى الملك وجهه بيديه صارخا بصوت عظيم: «يا ابني أبشالوم، يا أبشالوم ابني، ابني».","19:5":"فتوجه يوآب إلى البيت وقال للملك: «لقد أخجلت اليوم جميع رجالك الذين أنقذوك أنت وأبناءك وبناتك ونساءك ومحظياتك،","19:6":"بمحبتك لمبغضيك وبغضك لمحبيك، فقد أبديت اليوم بوضوح أنه لا اعتبار لديك للرؤساء ولا للعبيد، لأني أدركت اليوم أنه لو كان أبشالوم حيا وكلنا هلكنا، لطاب الأمر لك.","19:7":"فقم الآن واخرج واشرح قلوب رجالك، لأني قد أقسمت بالرب أنه إن لم تخرج، فلن يبقى معك أحد الليلة، فيكون هذا الأمر أسوأ عليك من كل كارثة أصابتك منذ صباك إلى الآن».","19:8":"فقام الملك وجلس عند بوابة المدينة. فذاع الخبر بين جميع أوساط الجيش أن الملك جالس عند البوابة، فأقبل الجيش إليه. أما الإسرائيليون فهربوا لائذين ببيوتهم.","19:9":"ونشبت خصومات بين جميع أسباط إسرائيل قائلين: «إن الملك قد أنقذنا من قبضة أعدائنا، وخلصنا من حكم الفلسطينيين، وها هو قد هرب من الأرض لينجو من أبشالوم.","19:10":"وأبشالوم الذي نصبناه ملكا علينا مات في الحرب. فالآن لماذا أنتم متقاعسون عن إرجاع الملك؟»","19:11":"وبعث الملك داود إلى صادوق وأبياثار الكاهنين قائلا: «اسألا شيوخ إسرائيل لماذا تكونون آخر من يطالب بعودة الملك إلى مقره، وقد بلغ مسامع الملك في بيته كل ما قيل في إسرائيل؟","19:12":"أنتم إخوتي وعظمي ولحمي، فلماذا تكونون آخر من يطالب بإرجاع الملك.","19:13":"وقولا لعماسا: ألست أنت من لحمي وعظمي؟ فليعاقبني الرب أشد عقاب ويزد، إن لم أجعلك طوال حياتك قائدا لجيشي بدل يوآب».","19:14":"فاستمال بذلك قلوب جميع رجال يهوذا كرجل واحد، فأرسلوا إليه يناشدونه الرجوع قائلين: «عد أنت وجميع رجالك».","19:15":"فرجع الملك حتى بلغ الأردن، فتوافد رجال يهوذا إلى الجلجال لاستقباله والعبور به نهر الأردن.","19:16":"وأسرع شمعي بن جيرا البنياميني، الذي من بحوريم، ورافق رجال يهوذا لاستقبال الملك داود،","19:17":"ومعه ألف رجل من سبط بنيامين، كما جاء صيبا خادم شاول ومعه أولاده الخمسة عشر وعبيده العشرون، وخاضوا نهر الأردن أمام الملك.","19:18":"وإذ اجتازوا المخاضة لمواكبة بيت الملك وعمل ما يستحوذ على رضاه، مثل شمعي بن جيرا أمام الملك عند عبوره الأردن وسجد له متوسلا","19:19":"قائلا: «ليغفر لي سيدي الملك إثمي ولا يذكر افتراء عبده عليه عندما خرج الملك من أورشليم، ولا يكتم ذلك في قلبه،","19:20":"لأن عبدك قد أدرك أني قد أخطأت، ها أنا قد جئت اليوم في طليعة بيت يوسف لاستقبال سيدي الملك».","19:21":"فقال أبيشاي بن صروية: «ألا ينبغي أن يقتل شمعي لأجل هذا؟ لقد شتم مختار الرب».","19:22":"فقال داود: «كفا عني يا ابني صروية، فلماذا تقاومانني؟ أيقتل اليوم أحد في إسرائيل؟ ألست أنا الآن ملك إسرائيل؟»","19:23":"ثم قال الملك لشمعي: «لن تموت». وأقسم له على ذلك.","19:24":"وكذلك جاء مفيبوشث حفيد شاول للقاء الملك، وكان قد أهمل الاعتناء برجليه ولحيته، ولم يغسل ثيابه منذ اليوم الذي غادر فيه الملك أورشليم إلى حين رجوعه سالما.","19:25":"وعندما جاء للقائه في أورشليم سأله الملك: «لماذا لم تأت معي يا مفيبوشث؟»","19:26":"فأجاب: «إن عبدك يا سيدي الملك أعرج، فقلت لنفسي. أسرج حماري وأركب عليه وأمضي مع الملك، ولكن صيبا وكيل أعمالي خدعني،","19:27":"ووشى بعبدك بهتانا إلى سيدي الملك، وسيدي الملك كملاك الله. فافعل ما يروق لك.","19:28":"إن كل بيت أبي لا يستحقون منك شيئا سوى الموت، ولكنك أكرمتني، فجعلت عبدك بين الآكلين على مائدتك، فأي حق لي بعد أطالب به الملك؟»","19:29":"فأجابه الملك: «كفاك حديثا عن شؤونك، لقد أمرت أن تقسم أنت وصيبا الحقول».","19:30":"فقال مفيبوشث: «فليأخذها كلها بعد أن عاد سيدي الملك إلى بيته بسلام».","19:31":"ونزل برزلاي الجلعادي من روجليم وعبر الأردن مع الملك ليشيعه من هناك.","19:32":"وكان برزلاي قد طعن في السن وبلغ الثمانين عاما، وكان قد عال الملك عند إقامته في محنايم لأنه كان رجلا ثريا جدا.","19:33":"فقال الملك لبرزلاي: «تعال معي لأورشليم فأقوم على إعالتك»","19:34":"فأجاب برزلاي: «كم بقي لي من العمر حتى أصعد مع الملك إلى أورشليم؟","19:35":"أنا اليوم قد بلغت الثمانين، فهل أستطيع أن أميز بين الطيب والرديء؟ وهل يلتذ عبدك بما يأكل ويشرب؟ وهل مازلت قادرا على الاستماع إلى أصوات المغنين والمغنيات؟ فلماذا يصبح عبدك عبئا على سيدي الملك؟","19:36":"ليرافق عبدك موكبك قليلا بعد عبورك نهر الأردن. ولكن علام يكافئني الملك هذه المكافأة؟","19:37":"دعني أرجع لأموت في مدينتي بجوار ضريح أبي وأمي، وها هو ولدي كمهام يذهب مع سيدي الملك فكافئه بما يحلو لك».","19:38":"فأجاب الملك: «ليرافقني كمهام فأجزل له ما يروق لك من مكافأة وكل ما تتمناه مني ألبيه لك».","19:39":"فاجتاز جميع الشعب نهر الأردن وكذلك فعل الملك. وقبل الملك برزلاي وباركه، ثم قفل هذا راجعا إلى محل إقامته.","19:40":"وتوجه الملك إلى الجلجال يرافقه كمهام وسائر شعب يهوذا الذين واكبوه مجتازين به نهر الأردن، وكذلك نصف شعب إسرائيل.","19:41":"واجتمع رجال إسرائيل وقالوا للملك: «لماذا أخذك إخوتنا رجال يهوذا خفية، وعبروا الأردن بالملك وبأهل بيته وبكل رجال داود؟»","19:42":"فأجاب رجال يهوذا رجال إسرائيل: «لأن الملك قريب لنا، فماذا يثير غيظكم في هذا الأمر؟ هل أكلنا شيئا من مؤونة الملك؟ هل نلنا مكافأة على ذلك؟»","19:43":"فقال رجال إسرائيل لرجال يهوذا: «إن لنا عشرة سهام في الملك، ونحن أولى منكم بداود، فلماذا استخففتم بنا؟ أولم نكن نحن أول من تحدث عن إرجاع ملكنا؟» فكان رد رجال يهوذا أغلظ من كلام رجال إسرائيل.","20:1":"وحدث أن كان هناك رجل لئيم يدعى شبع بن بكري من سبط بنيامين، فنفخ هذا بالبوق وقال: «ليس لنا نصيب في داود ولا قسم في ابن يسى، فليرجع كل رجل إلى خيمته يا إسرائيل».","20:2":"فتخلى كل رجال إسرائيل عن داود وتبعوا شبع بن بكري، وأما رجال يهوذا فلازموا ملكهم وواكبوه من الأردن إلى أورشليم.","20:3":"وعندما استقر الملك في مقره في أورشليم حجز المحظيات العشر اللواتي تركهن لحفظ القصر وكان يعولهن، ولكنه امتنع عن معاشرتهن، وبقين كالأرامل محجوزات حتى يوم وفاتهن.","20:4":"وقال الملك لعماسا: «احشد لي رجال يهوذا في ثلاثة أيام واحضر أنت إلى هنا».","20:5":"فانطلق عماسا ليجند رجال يهوذا، ولكنه تأخر عن الموعد الذي حدده له الملك.","20:6":"فقال داود لأبيشاي: «قد يسبب شبع الآن لنا أذى أكثر مما سببه أبشالوم، أسرع خذ حرسي الخاص وتعقبه لئلا يلجأ إلى مدن حصينة ويفلت من بين أيدينا».","20:7":"فمضى أبيشاي على رأس رجال يوآب والجلادين والسعاة والمحاربين الأشداء، واندفعوا من أورشليم ليتعقبوا شبع بن بكري.","20:8":"وعندما وصلوا عند الصخرة العظيمة في جبعون، أقبل إليهم عماسا. وكان يوآب مرتديا ثوبه العسكري متنطقا على حقويه بحزام معلق به سيف في غمده، فلما خرج للقائه اندلق السيف من الغمد.","20:9":"فقال يوآب لعماسا: «أتتمتع بالعافية يا أخي؟» وقبضت يد يوآب اليمنى على لحية عماسا وكأنه يهم بتقبيله.","20:10":"ولم يحترز عماسا من السيف الذي كان بيد يوآب، فطعنه به، فاندلقت أمعاؤه إلى الأرض ولم يثن عليه لأنه مات على الفور، وتابع يوآب وأبيشاي تعقبهما لشبع بن بكري.","20:11":"فوقف أحد غلمان يوآب عند جثة عماسا صائحا: «من هو معجب بيوآب وولاؤه لداود فليتبع يوآب».","20:12":"وكان عماسا راقدا في وسط الطريق غارقا في دمائه، ولما رأى الرجل أن كل الجنود المارين يتوقفون عنده، نقل جثة عماسا من الطريق إلى الحقل وغطاها بثوب.","20:13":"وما لبث، بعد نقل الجثة من الطريق، أن لحق كل جندي بيوآب لمطاردة شبع بن بكري.","20:14":"ودار شبع على جميع أسباط إسرائيل حتى آبل وبيت معكة وسائر منطقة البيريين فالتفوا حوله وانضموا إليه.","20:15":"وجاءت قوات يوآب وحاصرته في آبل بيت معكة، وأقاموا متراسا مرتفعا إزاء المدينة في مواجهة استحكامات السور وشرعوا في هدمه.","20:16":"فنادت امرأة حكيمة من المدينة: «اسمعوا، اسمعوا! قولوا ليوآب، ادن من هنا لأكلمك».","20:17":"فتقدم إليها، فقالت المرأة: «أأنت يوآب؟» فأجاب: «أنا هو». فقالت له: «أصغ إلى كلام أمتك». فقال: «أنا سامع»","20:18":"فتكلمت المرأة: «كانوا قديما يقولون: إن أردت الحصول على جواب (حكيم) فإنك تجده في آبل، وكان هذا يحسم كل جدال.","20:19":"أنا واحدة من بين بقية المسالمين في إسرائيل، وأنت تبغي تدمير مدينة هي أم في إسرائيل، فلماذا تريد أن تبتلع ميراث الرب؟»","20:20":"فأجاب يوآب: «معاذ الله، معاذ الله أن أبتلع أو أن أدمر.","20:21":"إن الأمر ليس كذلك، إنما هناك رجل من جبل أفرايم يدعى شبع بن بكري تطاول على الملك داود. سلموه وحده فأنصرف عن المدينة». فقالت المرأة ليوآب: «عما قليل يطرح إليك رأسه من على السور».","20:22":"وتداولت المرأة مع الشعب كله فأقنعتهم بسداد رأيها، فقطعوا رأس شبع بن بكري وألقوه إلى يوآب، فنفخ بالبوق، ففكوا الحصار عن المدينة، وعاد كل واحد إلى بيته، وأما يوآب فرجع إلى الملك في أورشليم.","20:23":"وكان يوآب القائد العام على جميع جيش إسرائيل، وبناياهو بن يهوياداع قائد حرس الملك،","20:24":"وأدورام مسؤولا عن فرق الأشغال الشاقة، ويهوشافاط بن أخيلود المسجل التاريخي،","20:25":"وشيوا كاتب الملك، وصادوق وأبياثار كاهنين.","20:26":"أما عيرا اليائيري فكان كاهن داود الخاص.","21:1":"وحدثت مجاعة في أثناء حكم داود استمرت ثلاث سنوات متتالية، فالتمس داود وجه الرب. فأجابه الرب: «هذا من أجل ما ارتكبه شاول وأهل بيته الملطخة أيديهم بدماء الجبعونيين الذين قتلوهم.","21:2":"فاستدعى الملك الجبعونيين، وهم من بقايا شعب الأموريين الذين وقع معهم الإسرائيليون معاهدة صلح، ولكن شاول سعى للقضاء عليهم من فرط غيرته على بني يهوذا وإسرائيل.","21:3":"وقال داود لهم: «ماذا أصنع لكم؟» كيف يمكن أن أعوض عما نالكم من ضرر، فتدعون بالبركة لميراث الرب؟»","21:4":"فأجابه الجبعونيون: «لا نريد مالا ولا فضة من شاول ولا من أهل بيته، ولا نبغي أن نميت أحدا في إسرائيل». فقال لهم: «مهما طلبتم أفعله لكم»","21:5":"فقالوا للملك: «أعطنا سبعة رجال من بني الرجل الذي أفنانا وتآمر علينا ليبيدنا فلا نقيم في كل أرض إسرائيل،","21:6":"فنصلبهم للرب في جبعة شاول مختار الرب». فأجاب الملك: «أنا أعطيكم».","21:7":"وأشفق الملك على مفيبوشث بن يوناثان من أجل ما بين داود ويوناثان بن شاول من عهد الرب،","21:8":"فأخذ الملك، أرموني ومفيبوشث ابني رصفة ابنة أية اللذين ولدتهما لشاول، وأبناء ابنة شاول الخمسة الذين أنجبتهم لعدريئيل ابن برزلاي المحولي.","21:9":"وسلمهم إلى الجبعونيين، فصلبوهم على الجبل في حضرة الرب. فقتل السبعة معا في بداية موسم حصاد الشعير.","21:10":"فأخذت رصفة ابنة أية مسحا فرشته على الصخر من بداية الحصاد حتى هطول الأمطار على الجثث، ومنعت الجوارح من الانقضاض عليها نهارا، والوحوش من افتراسها ليلا.","21:11":"وعندما بلغ داود ما فعلته رصفة ابنة أية محظية شاول،","21:12":"ذهب وأخذ عظام شاول وعظام يوناثان ابنه من أهل يابيش جلعاد، الذين سرقوها من شارع بيت شان حيث علقها الفلسطينيون بعد قضائهم عليهما في جلبوع،","21:13":"فأصعد من هناك عظام شاول ويوناثان ابنه، كما تم جمع عظام المصلوبين.","21:14":"ودفنوها في أرض بنيامين في صيلع في قبر قيس أبي شاول. وعندما تم تنفيذ ما أمر به الملك استجاب الله الصلاة من أجل إخصاب الأرض.","21:15":"ودارت حرب بعد ذلك بين الفلسطينيين وإسرائيل، فخاض داود ورجاله المعركة لمحاربة الفلسطينيين، ولكن الإعياء أصاب داود.","21:16":"وهم يشبي بن بنوب، أحد أبناء رافا، أن يقتل داود، وكان وزن رمحه النحاسي ثلاث مئة شاقل (نحو ثلاثة كيلوجرامات ونصف)، وقد تقلد سيفا جديدا.","21:17":"فأنجده أبيشاي بن صروية، وضرب الفلسطيني وقتله. حينئذ أقسم رجال داود عليه قائلين: «لا تخرج معنا بعد الآن إلى الحرب، ولا تطفئ بموتك سراج إسرائيل».","21:18":"ونشبت بعد ذلك معركة أخرى مع الفلسطينيين في جوب، فقتل سبكاي الحوشي ساف أحد أبناء رافا.","21:19":"ووقعت حرب ثالثة في جوب مع الفلسطينيين قتل فيها ألحانان بن يعري البيتلحمي جليات الجتي الذي كانت قناة رمحه في حجم نول النساجين.","21:20":"وجرت معركة رابعة في جت، كان من المحاربين فيها رجل طويل القامة له ست أصابع في كل يد وفي كل قدم. فكانت في جملتها أربعة وعشرين إصبعا، وهو أيضا من أبناء رافا.","21:21":"وعندما حقر إسرائيل، قتله يوناثان بن شمعى أخي داود.","21:22":"وهكذا قتل داود ورجاله هؤلاء الأربعة الذين ولدوا لرافا في جت.","22:1":"وخاطب داود الرب بأبيات هذا النشيد في اليوم الذي أنقذه فيه الرب من كل أعدائه، ومن شاول:","22:2":"«الرب صخرتي وحصني ومنقذي.","22:3":"إلهي صخرتي به أحتمي، ترسي وركن خلاصي. هو حصني وملجإي ومخلصي. أنت تخلصني من الظالمين.","22:4":"أدعو الرب الجدير بكل حمد فيخلصني من أعدائي.","22:5":"طوقتني أمواج الموت وسيول الهلاك غمرتني.","22:6":"أحاطت بي حبال الهاوية، وأطبقت علي فخاخ الموت.","22:7":"في ضيقي دعوت الرب، وبإلهي استغثت، فسمع صوتي من هيكله، وبلغ صراخي أذنيه.","22:8":"عندئذ ارتجت الأرض وتزلزلت. ارتجفت أساسات السماوات واهتزت لأن الرب غضب.","22:9":"نفث أنفه دخانا، واندلعت نار آكلة من فمه، فاتقد منها جمر.","22:10":"طأطأ السماوات ونزل، فكانت الغيوم المتجهمة تحت قدميه.","22:11":"امتطى مركبة من ملائكة الكروبيم وطار وتجلى على أجنحة الريح.","22:12":"أحاطت به الظلمة كالمظلات واكتنفته السحب المتكاثفة واللجج.","22:13":"من بهاء طلعته توهجت جمرات نار.","22:14":"أرعد الرب من السماء وأطلق العلي صوته.","22:15":"أطلق سهامه فبدد الأعداء، وأرسل بروقه فأزعجهم.","22:16":"ظهرت مجاري المياه العميقة وانكشفت أسس المسكونة من زجر الرب ومن ريح أنفه اللافحة.","22:17":"مد الرب يده من العلى وأمسكني، انتشلني من السيول الغامرة.","22:18":"أنقذني من عدوي القوي، وخلصني من مبغضي لأنهم كانوا أقوى مني.","22:19":"تصدوا لي في يوم بليتي، فكان الرب سندي.","22:20":"اقتادني إلى موضع رحيب، أنقذني لأنه سر بي.","22:21":"يكافئني الرب حسب بري. ويعوضني حسب طهارة يدي.","22:22":"لأني سلكت دائما في طرق الرب، ولم أعص إلهي.","22:23":"جعلت أحكامه دائما نصب عيني ولم أحد عن فرائضه.","22:24":"فكنت كاملا لديه، وصنت نفسي من الإثم.","22:25":"فيكافئني الرب وفقا لبري، وبحسب طهارتي أمام عينيه.","22:26":"مع الرحيم تكون رحيما، ومع الكامل تكون كاملا.","22:27":"مع الطاهر تكون طاهرا، ومع المعوج تكون معوجا.","22:28":"أنت تنقذ الشعب المتضايق، أما عيناك فتراقبان المتغطرسين لتخفضهم.","22:29":"يا رب أنت سراجي. الرب يضيء ظلمتي.","22:30":"لأني بك أقتحم جيشا، وبقوة إلهي اخترقت أسوارا.","22:31":"ما أكمل طريق الرب!، إن كلمته نقية، وهو متراس يحمي جميع الملتجئين إليه.","22:32":"لأنه من هو إله غير الرب؟ ومن هو صخرة سوى إلهنا؟","22:33":"إنه الله الذي يسلحني بالقوة، ويجعل طريقي كاملا.","22:34":"يجعل رجلي كرجلي الإيل ويقيمني آمنا على المرتفعات.","22:35":"تدرب يدي على فن الحرب فتشد ذراعاي قوسا من نحاس.","22:36":"تعطيني ترس خلاصك، وبلطفك تعظمني.","22:37":"وسعت طريقي تحت قدمي فلم تتعثر رجلاي.","22:38":"أطارد أعدائي فأدركهم، ولا أرجع حتى أبيدهم.","22:39":"أقضي عليهم وأسحقهم، فلا يستطيعون النهوض، بل يسقطون تحت قدمي.","22:40":"تمنطقني بحزام من القوة تأهبا للقتال وتخضع لسلطاني المتمردين علي.","22:41":"تجعل أعدائي يولون الأدبار هربا مني. وأفني الذين ييغضونني.","22:42":"يستغيثون ولا من مخلص، ينادون الرب فلا يستجيب لهم.","22:43":"فأسحقهم كغبار الأرض، ومثل طين الأسواق أدقهم وأدوسهم.","22:44":"تنقذني من مخاصمات الشعب، وتجعلني سيدا للأمم حتى صار شعب لم أكن أعرفه عبدا يخدمني.","22:45":"يقبل الغرباء نحوي متذللين، وحالما يسمعون أمري يلبونه.","22:46":"الغرباء يخورون، يخرجون من حصونهم مرتعدين.","22:47":"حي هو الرب، ومبارك صخرتي. ومتعال إله خلاصي.","22:48":"الإله المنتقم لي، الذي يخضع الشعوب لسلطاني.","22:49":"منقذي من أعدائي، رافعي على المتمردين ومن الرجل الطاغي يخلصني","22:50":"لذلك أسبحك يا رب بين الأمم وأرنم لاسمك.","22:51":"يا مانح الخلاص العظيم لملكه وصانع الرحمة لمسيحه، لداود ونسله إلى الأبد.","23:1":"وهذه كلمات داود الأخيرة: هذا ما أوحي به إلى داود بن يسى، وما تنبأ به الرجل الذي عظمه العلي، الرجل الذي مسحه إله يعقوب. هذا هو مرتل إسرائيل المحبوب.","23:2":"«تكلم روح الرب بفمي، وكلمته نطق بها لساني.","23:3":"إله إسرائيل تكلم، صخرة إسرائيل قال لي: عندما يحكم إنسان بعدل على الناس ويتسلط بمخافة الله،","23:4":"فإنه يشرق عليهم كنور الفجر، وكالشمس يشع عليهم في صباح صاف، وكالمطر الذي يستنبت عشب الأرض.","23:5":"أليست هكذا علاقة بيتي بالله؟ ألم يبرم معي عهدا أبديا كاملا ومؤمنا؟ ألا يكلل خلاصي بالفلاح ويضمن تحقيق رغائبي؟","23:6":"أما الأشرار فيطرحون جميعا كالشوك، لأنهم (يجرحون) اليد التي تلمسهم.","23:7":"وكل من يمسهم يتسلح بحديد وقناة رمح، وتلتهمهم النار جميعا في مكانهم».","23:8":"وهذه أسماء رجال داود الأبطال: يوشيب بشبث التحكموني، وكان قائد الثلاثة، هاجم برمحه ثماني مئة وقتلهم دفعة واحدة.","23:9":"ويليه ألعازار بن دودو بن أخوخي، وهو أحد الأبطال الثلاثة الذين كانوا مع داود حين عيروا الفلسطينيين (في أفس دميم) المجتمعين هناك للحرب، وعندما تقهقر رجال إسرائيل،","23:10":"صمد هو وظل يهاجم الفلسطينيين حتى كلت يده ولصقت بالسيف، ووهبه الرب نصرا مؤزرا في ذلك اليوم، وما لبث أن رجع الشعب لنهب الغنائم فقط.","23:11":"ويعقبه شمة بن أجي الهراري. وكان الفلسطينيون قد حشدوا جيشا في قطعة حقل مزروعة بالعدس، فهرب الإسرائيليون أمامهم.","23:12":"لكن شمة ثبت في مكانه وسط قطعة الحقل، وقضى على الفلسطينيين، وأنقذ الحقل منهم، فوهبه الله النصر عليهم.","23:13":"وفي موسم الحصاد، أقبل هؤلاء الثلاثة من بين الثلاثين رئيسا إلى داود اللاجئ إلى مغارة عدلام، وكان جيش الفلسطينيين آنئذ معسكرا في وادي الرفائيين،","23:14":"بينما داود معتصما في الحصن، وحامية الفلسطينيين نازلة في بيت لحم.","23:15":"فتأوه داود قائلا: «من يسقيني ماء من بئر بيت لحم القائمة عند بوابة المدينة؟»","23:16":"فاقتحم الأبطال الثلاثة معسكر الفلسطينيين، وجلبوا ماء من بئر بيت لحم القائمة عند البوابة، وحملوه إلى داود. فلم يشأ أن يشربه بل سكبه للرب،","23:17":"قائلا: «معاذ الله أن أفعل هذا! إنه دم الرجال الذين جازفوا بأنفسهم». وهكذا أبى أن يشربه. هذا ما قام به هؤلاء الأبطال الثلاثة.","23:18":"وكان أبيشاي أخو يوآب وابن صروية رئيس ثلاثة أيضا. هذا جابه برمحه ثلاث مئة وقتلهم، فذاعت شهرته بين الثلاثة،","23:19":"وارتفعت مكانته عليهم وصار لهم رئيسا، إلا أنه لم يصل إلى مرتبة الثلاثة الأول.","23:20":"وكان بناياهو بن يهوياداع محاربا مجيدا من قبصئيل، هذا صرع بطلي موآب، ونزل إلى وسط جب في يوم مثلج وقتل أسدا،","23:21":"كما قضى على رجل مصري عملاق كان يحمل بيده رمحا، فتصدى له بعصا وخطف الرمح من يده وقتله به.","23:22":"هذا ما صنعه بناياهو بن يهوياداع فذاعت شهرته بين الأبطال الثلاثة.","23:23":"وارتفعت مكانته على الثلاثين قائدا، ولكنه لم يبلغ مرتبة الثلاثة الأول فعينه داود قائدا لحرسه الخاص.","23:24":"وكان عسائيل أخو يوآب واحدا من الثلاثين رئيسا، وكذلك ألحانان بن دودو من بيت لحم،","23:25":"وشمة الحرودي وأليقا الحرودي","23:26":"وحالص الفلطي، وعيرا بن عقيش التقوعي","23:27":"وأبيعزر العناثوثي، ومبوناي الحوشاتي.","23:28":"وصلمون الأخوخي، ومهراي النطوفاتي.","23:29":"وخالب بن بعنة النطوفاتي، وإتاي بن ريباي من جبعة بني بنيامين،","23:30":"وبنايا الفرعتوني، وهداي من أودية جاعش.","23:31":"وأبو علبون العرباتي، وعزموت البرحومي.","23:32":"وأليحبا الشعلبوني، ويوناثان من بني ياشن.","23:33":"وشمة الهراري، وأخيآم بن شارار الأراري،","23:34":"وأليفلط بن أحسباي ابن المعكي، وأليعام بن أخيتوفل الجيلوني.","23:35":"وحصراي الكرملي، وفعراي الأربي،","23:36":"ويجآل بن ناثان من صوبة، وباني الجادي،","23:37":"وصالق العموني، ونحراي البئيروتي حامل سلاح يوآب بن صروية،","23:38":"وعيرا اليثري، وجارب اليثري،","23:39":"وأوريا الحثي. وهم في جملتهم سبعة وثلاثون بطلا.","24:1":"ثم عاد فاحتدم غضب الرب على إسرائيل، فأثار داود عليهم قائلا: «هيا قم بإحصاء إسرائيل ويهوذا».","24:2":"فقال الملك ليوآب رئيس جيشه: «تجول بين أسباط إسرائيل من دان إلى بئر سبع، وقم بإحصاء الشعب، فأعرف جملة عددهم»","24:3":"فأجاب يوآب: «ليضاعف الرب الشعب مئة مثل وأنت تتمتع بطول العمر، ولكن لماذا يرغب سيدي الملك في مثل هذا الأمر؟»","24:4":"ولكن أمر الملك غلب على رأي يوآب وعلى رؤساء الجيش، فانصرف يوآب وكبار ضباطه من عند الملك لإحصاء شعب إسرائيل.","24:5":"فاجتازوا نهر الأردن وأقاموا جنوبي مدينة عروعير الواقعة وسط وادي جاد مقابل يعزير.","24:6":"وقدموا إلى جلعاد إلى أرض تحتيم في حدشي، ثم توجهوا نحو دان يعن، واستداروا إلى صيدون.","24:7":"ثم انطلقوا إلى حصن صور وسائر مدن الحويين والكنعانيين، ومن هناك مضوا إلى جنوبي يهوذا إلى بئر سبع.","24:8":"وبعد أن طافوا في جميع أرجاء أرض إسرائيل، رجعوا في نهاية تسعة أشهر وعشرين يوما إلى أورشليم.","24:9":"ورفع يوآب تقريره المتضمن جملة إحصاء الشعب إلى الملك، فكان عدد الإسرائيليين القادرين على حمل السلاح ثماني مئة ألف من إسرائيل، وخمس مئة ألف من يهوذا.","24:10":"وبعد أن تم إحصاء الشعب اعترى الندم قلب داود، فتضرع إلى الرب قائلا: «أخطأت جدا بما ارتكبته، فأرجوك يا رب أن تزيل إثم عبدك لأنني تصرفت تصرفا أحمق».","24:11":"وقبل أن ينهض داود من نومه صباحا، قال الرب لجاد النبي، رائي داود:","24:12":"«اذهب وقل لداود: هذا ما يقوله الرب، أنا أعرض عليك ثلاثة أمور، فاختر لنفسك واحدا منها فأجريه عليك».","24:13":"فمثل جاد أمام داود وقال: «اختر إما أن تجتاح البلاد سبع سني جوع، أو تهرب ثلاثة أشهر أمام أعدائك وهم يتعقبونك، أو يتفشى وبأ في أرضك طوال ثلاثة أيام. ففكر في الأمر مليا وأخبرني عما استقر عليه ردك على من أرسلني؟»","24:14":"فأجاب داود: «قد ضاق بي الأمر، ولكن خير لي أن أقع في يد الرب، لأن مراحمه كثيرة من أن أقع بين يدي إنسان».","24:15":"فأفشى الرب وبأ في إسرائيل من الصباح حتى نهاية ثلاثة أيام، فمات من الشعب من دان إلى بئر سبع سبعون ألف رجل.","24:16":"ومد ملاك الرب يده فوق أورشليم ليهلكها ولكن أخذت الرب رأفة على ما أصاب الشعب من شر وقال للملاك المهلك: «كفى، رد يدك». وكان ملاك الرب عندئذ قد بلغ بيدر أرونة اليبوسي.","24:17":"فقال داود للرب عندما شاهد الملاك المهلك «أنا هو المخطئ والمذنب، وأما هؤلاء الخراف فماذا جنوا؟ ليحل عقابك علي وعلى بيت أبي».","24:18":"فجاء جاد إلى داود في ذلك اليوم وقال له: «اذهب إلى بيدر أرونة اليبوسي وشيد مذبحا للرب فيه».","24:19":"فانطلق داود حسب كلام جاد الذي أمره به الرب.","24:20":"وعندما رأى أرونة الملك ورجاله قادمين نحوه، خرج للقائه وخر ساجدا بوجهه على الأرض،","24:21":"وسأل: «لماذا جاء سيدي الملك إلى بيت عبده؟» فأجابه داود: «لأشتري منك البيدر حتى أبني للرب مذبحا فتكف الضربة عن الناس».","24:22":"فقال أرونة لداود: «ليأخذه سيدي الملك ويقرب عليه ما يروق له. انظر! ها هي البقر للمحرقات، والنوارج وأنيار البقر لتكون حطبا؛","24:23":"إن أرونة يقدم كل هذا للملك». ثم أضاف: «ليرض الرب إلهك عنك».","24:24":"فقال الملك: «لا، بل أشتري منك كل هذا بثمن، إذ لن أصعد للرب محرقات مجانية». فاشترى داود البيدر والبقر بخمسين شاقلا من الفضة (نحو ست مئة جرام).","24:25":"وشيد داود هناك مذبحا للرب قرب عليه محرقات وذبائح سلام، فاستجاب الرب الصلاة من أجل الأرض وكف الوبأ عن إسرائيل."};
